// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Cumhuriyet dönemi şiiri: topluluklar ve şairler (orta).
const ozLiterature8Orta = <(String, String, List<String>, String)>[
  ('Yedi Meşale topluluğunun yedi üyesi arasında şiir yazmayan, ürünlerini yalnızca hikâye türünde veren isim kimdir?', 'Kenan Hulusi Koray', ['Ziya Osman Saba', 'Vasfi Mahir Kocatürk', 'Muammer Lütfi Bahşi'], 'Kenan Hulusi Koray topluluğun tek düzyazı yazarıdır; hikâyeleriyle katılmıştır. Diğer altı üye şairdir.'),
  ('Yedi Meşaleciler\'in yeni bir şiir arayışında örnek aldığı yerli şairler hangi seçenekte birlikte verilmiştir?', 'Ahmet Haşim ve Yahya Kemal', ['Mehmet Emin ve Ziya Gökalp', 'Tevfik Fikret ve Cenap Şahabettin', 'Namık Kemal ve Ziya Paşa'], 'Topluluk, Beş Hececiler\'in memleketçi tekdüzeliğinden kaçarken Ahmet Haşim\'in imgeci ve Yahya Kemal\'in ahenkçi şiirinden beslenmiştir.'),
  ('Yedi Meşale topluluğu dağıldıktan sonra üyelerinden hangisi şiirden çok edebiyat tarihi, tiyatro ve halk tiyatrosu araştırmalarıyla tanınmıştır?', 'Cevdet Kudret Solok', ['Ziya Osman Saba', 'Vasfi Mahir Kocatürk', 'Muammer Lütfi Bahşi'], 'Cevdet Kudret, Türk Edebiyatında Hikâye ve Roman, Karagöz ve Ortaoyunu gibi inceleme eserleriyle tanınır.'),
  ('Yedi Meşale ortak kitabının önsözünde topluluğun benimsediği ilkeler \'canlılık, samimiyet, yenilik\' olarak sıralanır. Bu ilkeler en çok hangi duruma bir tepki olarak okunabilir?', 'Hececilerin aynı konuları tekrarlayan memleketçi şiirine', ['Servet-i Fünun\'un toplumsal konulardan uzak duran salon şiirine', 'Garip\'in ölçü ve kafiyeyi reddetmesine', 'İkinci Yeni\'nin anlamı kapalı imgeciliğine'], '1928\'de ortaya çıkan topluluk, Beş Hececiler\'in hep Anadolu ve memleket temalarını işleyen kalıplaşmış şiirine karşı çıkmıştır. Garip ve İkinci Yeni ondan sonradır.'),
  ('Yedi Meşaleciler topluluğunun Türk şiirinde kalıcı bir çığır açamamasının en önemli nedeni olarak hangisi gösterilebilir?', 'Ortak bir sanat kuramından çok genel ve belirsiz ilkelere dayanması', ['Üyelerinin tamamının şiiri bırakıp yalnızca roman ve hikâyeye geçmesi', 'Yalnızca aruz ölçüsüyle yazmakta ısrar etmesi', 'Dergilerinin yasaklanarak toplatılması'], 'Canlılık, samimiyet ve yenilik ilkeleri somut bir poetikaya dönüşmemiş; topluluk kısa sürede dağılmış, üyeler ayrı yollara gitmiştir.'),
  ('Ziya Osman Saba\'nın 1943\'te yayımlanan ilk şiir kitabı hangisidir?', 'Sebil ve Güvercinler', ['Geçen Zamanın Ardından', 'Nefes Almak', 'Kapalıçarşı'], 'Sebil ve Güvercinler (1943) Ziya Osman\'ın ilk kitabıdır; Geçen Zaman 1947\'de, Nefes Almak 1957\'de çıkmıştır. Kapalıçarşı Necatigil\'indir.'),
  ('Cahit Sıtkı Tarancı\'nın yakın dostuna yazdığı ve ölümünden sonra kitaplaşan mektuplarının alıcısı olan Yedi Meşale şairi kimdir?', 'Ziya Osman Saba', ['Yaşar Nabi Nayır', 'Cevdet Kudret Solok', 'Sabri Esat Siyavuşgil'], 'Cahit Sıtkı\'nın mektupları Ziya\'ya Mektuplar adıyla yayımlanmıştır; alıcı Ziya Osman Saba\'dır.'),
  ('Ziya Osman Saba\'nın şiiri ile Necip Fazıl\'ın şiiri karşılaştırıldığında hangi fark öne çıkar?', 'Ziya Osman\'da sakin bir teslimiyet, Necip Fazıl\'da ürpertili bir metafizik bunalım vardır.', ['Ziya Osman toplumcu, Necip Fazıl bireyci bir şairdir.', 'Ziya Osman serbest ölçüyü ve kapalı imgeyi, Necip Fazıl aruzu ve divan biçimlerini benimsemiştir.', 'Ziya Osman yalnız destan, Necip Fazıl yalnız hiciv yazmıştır.'], 'İkisi de Tanrı\'ya yönelir; ancak Ziya Osman ev, çocukluk ve huzur içinde sığınma dile getirirken Necip Fazıl korku, şüphe ve iç çatışmayı işler.'),
  ('Yaşar Nabi Nayır\'ın Varlık dergisine ek olarak kurduğu ve uzun yıllar Türk şiirinin önemli kitaplarını basan kuruluş hangisidir?', 'Varlık Yayınları', ['Yapı Kredi Yayınları', 'Remzi Kitabevi', 'de Yayınevi'], 'Yaşar Nabi, derginin yanında Varlık Yayınları\'nı kurarak cep kitapları dizisiyle pek çok yazarı geniş okura ulaştırmıştır.'),
  ('Cumhuriyet\'in onuncu yılı için 1933\'te bestelenen ve \'Çıktık açık alınla on yılda her savaştan\' diye başlayan marşın sözlerini hangi iki şair birlikte yazmıştır?', 'Faruk Nafiz Çamlıbel ve Behçet Kemal Çağlar', ['Kemalettin Kamu ve Orhan Seyfi Orhon', 'Arif Nihat Asya ve Ahmet Kutsi Tecer', 'Yusuf Ziya Ortaç ve Halit Fahri Ozansoy'], 'Onuncu Yıl Marşı\'nın sözleri Behçet Kemal Çağlar ile Faruk Nafiz Çamlıbel\'e, bestesi Cemal Reşit Rey\'e aittir.'),
  ('Dede Korkut Kitabı\'nın bilimsel yayımını hazırlayan Orhan Şaik Gökyay, şair olarak daha çok hangi şiiriyle tanınır?', 'Bu Vatan Kimin', ['Çanakkale Destanı', 'Memleket İsterim', 'Bingöl Çobanları'], 'Orhan Şaik Gökyay\'ın vatan sevgisini işleyen \'Bu Vatan Kimin\' şiiri okul kitaplarına girmiş ve çok sevilmiştir.'),
  ('Arif Nihat Asya\'nın İstanbul\'un fethini coşkuyla anlatan ve sıkça bestelenip okunan şiiri hangisidir?', 'Fetih Marşı', ['Akıncılar', 'Kuvâyi Milliye', 'Han Duvarları'], 'Fetih Marşı Arif Nihat Asya\'nındır. Akıncılar Yahya Kemal\'in, Kuvâyi Milliye Nazım Hikmet\'in, Han Duvarları Faruk Nafiz\'in şiiridir.'),
  ('Arif Nihat Asya\'nın dört dizelik bir divan nazım biçimiyle yazdığı şiirleri topladığı eser hangisidir?', 'Rubâiyyât-ı Ârif', ['Kendi Gök Kubbemiz', 'Divançe', 'Çile'], 'Arif Nihat Asya hece ve aruzu birlikte kullanmış, rubailerini Rubâiyyât-ı Ârif adıyla yayımlamıştır. Divançe Necatigil\'in, Çile Necip Fazıl\'ın eseridir.'),
  ('Ahmet Hamdi Tanpınar\'ın sağlığında yayımlanan tek şiir kitabı hangi adı taşır?', 'Şiirler', ['Beş Şehir', 'Göl Saatleri', 'Kendi Gök Kubbemiz'], 'Tanpınar şiirlerini ancak 1961\'de Şiirler adlı ince bir kitapta toplamıştır. Beş Şehir onun deneme kitabıdır.'),
  ('Tanpınar\'ın \'Bursa\'da eski bir camii avlusu, / Küçük şadırvanda şakırdayan su\' dizeleriyle başlayan şiirinde hangi kavram merkezdedir?', 'Geçmişin şimdiki ana sızdığı bir zaman duygusu', ['Köylünün toprak üzerindeki hak arayışı', 'Büyük şehirde makineleşmenin ve fabrika hayatının eleştirisi', 'Savaş meydanındaki kahramanlık coşkusu'], '\'Bursa\'da Zaman\' şiirinde şair tarihî mekânın içinde geçmiş ile şimdinin birleştiği, durmuş gibi görünen bir zamanı yaşar.'),
  ('Ahmet Muhip Dıranas, uzun yıllar dergilerde yayımladığı şiirlerini ancak 1974\'te tek bir kitapta toplamıştır. Bu durum onun hangi yönünü yansıtır?', 'Az ama özenle yazan, şiirini titizlikle süzen bir şair olmasını', ['Şiiri hiç önemsemeyip yalnızca roman ve tiyatroya ağırlık vermiş olmasını', 'Şiirlerinin sansürle tamamen toplatılmasını', 'Yalnız halk şiiri derlemeleri yapmış olmasını'], 'Dıranas biçime ve ahenge son derece özen gösteren, az yazan bir şairdir; Şiirler adlı tek kitabı geç yayımlanmıştır.'),
  ('Ahmet Muhip Dıranas\'ın İspanyolca \'unutuş\' anlamına gelen bir sözcüğü başlık yaptığı şiiri hangisidir?', 'Olvido', ['Mona Roza', 'Üvercinka', 'Lavinia'], 'Olvido İspanyolcada unutma, unutuş demektir; Dıranas\'ın aynı adlı şiiri aşk ve hatıranın silinişini işler. Mona Roza Karakoç\'un, Lavinia Özdemir Asaf\'ın şiiridir.'),
  ('Cumhuriyet Halk Partisi\'nin 1946\'da düzenlediği şiir yarışmasında birincilik ödülünü kazanan şiir hangisidir?', 'Otuz Beş Yaş', ['Cebbaroğlu Mehemmed', 'Fahriye Abla', 'Han Duvarları'], 'Cahit Sıtkı Tarancı \'Otuz Beş Yaş\' ile birinci olmuş, Attila İlhan \'Cebbaroğlu Mehemmed\' ile ikincilik almıştır.'),
  ('Cahit Sıtkı Tarancı\'nın ölümünden sonra 1957\'de yayımlanan şiir kitabı, adıyla da şairin yokluğunu sezdirir. Bu kitap hangisidir?', 'Sonrası', ['Ömrümde Sükût', 'Düşten Güzel', 'Geçen Zaman'], 'Şair 1956\'da Viyana\'da ölmüş, son şiirleri bir yıl sonra Sonrası adıyla basılmıştır. Geçen Zaman Ziya Osman Saba\'nındır.'),
  ('Cahit Sıtkı Tarancı\'nın Düşten Güzel kitabındaki bazı şiirlerde dilin sadeleşmesi ve konuşma havasının belirginleşmesi hangi etkiyle açıklanır?', 'Garip şiirinin yalınlık anlayışının etkisi', ['İkinci Yeni\'nin kapalı imge anlayışının etkisi', 'Divan şiirine dönüş isteğinin etkisi', 'Fütürist manifestonun etkisi'], '1940\'larda yaygınlaşan Garip anlayışı Cahit Sıtkı\'nın sonraki şiirlerinde daha sade ve günlük bir söyleyişe yol açmıştır. İkinci Yeni bu kitaptan sonra ortaya çıkmıştır.'),
  ('Necip Fazıl Kısakürek\'in 1925\'te yayımlanan ilk şiir kitabı hangisidir?', 'Örümcek Ağı', ['Ben ve Ötesi', 'Sonsuzluk Kervanı', 'Sebil ve Güvercinler'], 'Örümcek Ağı (1925) ilk kitabıdır; Kaldırımlar 1928\'de, Ben ve Ötesi 1932\'de, Sonsuzluk Kervanı 1955\'te çıkmıştır.'),
  ('Necip Fazıl\'ın Büyük Doğu\'dan önce, 1936\'da çıkardığı ve kısa süren sanat-edebiyat dergisi hangisidir?', 'Ağaç', ['Diriliş', 'Hisar', 'Mavera'], 'Ağaç dergisi 1936\'da Necip Fazıl tarafından yayımlanmıştır. Diriliş Sezai Karakoç\'un, Hisar Mehmet Çınarlı ve arkadaşlarının, Mavera ise 1970\'lerde bir grup İslamcı şairin dergisidir.'),
  ('Necip Fazıl\'ın 1934\'te tanıştığı ve hayatında köklü bir değişime yol açan mürşidi Abdülhakim Arvasi ile ilişkisini anlattığı eseri hangisidir?', 'O ve Ben', ['Çile', 'Reis Bey', 'Sabır Taşı'], 'O ve Ben, Necip Fazıl\'ın Abdülhakim Arvasi\'ye bağlanışını ve iç dönüşümünü anlattığı hatıra-itiraf niteliğinde bir eserdir.'),
  ('Necip Fazıl\'ın şiirlerinin 1934 öncesi ve sonrası olarak iki döneme ayrılması hangi değişime dayanır?', 'Bunalım ve arayıştan tasavvufi-İslami bir inanç şiirine yönelmesine', ['Aruzdan tamamen serbest ölçüye geçmesine', 'Bireysel şiirden, sınıf mücadelesini işleyen toplumcu gerçekçi şiire geçmesine', 'Şiiri bırakıp yalnız roman yazmaya başlamasına'], 'İlk dönemde ölüm korkusu, şehir ve yalnızlık bunalımı baskındır; Arvasi ile tanıştıktan sonra şiiri belirgin bir dinî-tasavvufi kimlik kazanır.'),
  ('Necip Fazıl\'ın Sakarya Nehri\'ni bir milletin kaderini ve ruhunu simgeleyen bir varlık olarak seslendirdiği şiiri hangisidir?', 'Sakarya Türküsü', ['Çoban Çeşmesi', 'Kuvâyi Milliye Destanı', 'Bu Vatan Kimin'], 'Sakarya Türküsü\'nde nehir, yolunu arayan ve çile çeken bir milletin simgesine dönüşür. Çoban Çeşmesi Faruk Nafiz\'in, Bu Vatan Kimin Orhan Şaik\'in şiiridir.'),
  ('Necip Fazıl\'ın şehirli insanın yalnızlığını ve geçiciliğini, yabancı yataklar ve kiralık odalar üzerinden işlediği şiiri hangisidir?', 'Otel Odaları', ['Fahriye Abla', 'Kitabe-i Seng-i Mezar', 'Masa da Masaymış'], 'Otel Odaları şiirinde Necip Fazıl, kimsesiz şehir insanının ürperti dolu iç dünyasını odalar imgesiyle verir.'),
  ('Necip Fazıl\'ın tiyatro eserleri arasında yer almayan hangisidir?', 'Köşebaşı', ['Tohum', 'Reis Bey', 'Para'], 'Tohum, Reis Bey ve Para Necip Fazıl\'ın oyunlarıdır; Köşebaşı Ahmet Kutsi Tecer\'e aittir.'),
  ('Necip Fazıl ile Ziya Osman Saba\'nın şiirleri birlikte okunduğunda ikisinde de görülen ortak bir yön hangisidir?', 'Ölüm ve Tanrı düşüncesine yönelen bireysel bir lirizm', ['Sınıf mücadelesini ve emekçinin haklarını öne çıkaran bir söylem', 'Ölçü ve kafiyeye karşı çıkan bir tutum', 'Anlamı bilinçli olarak dağıtan absürt bir dil'], 'İki şair de 1930-40\'larda bireysel duyarlılığı, ölümü ve Tanrı\'ya yönelişi işleyen, toplumcu olmayan bir şiir yazmıştır.'),
  ('Necip Fazıl\'ın şiirinin Türk şiirindeki yeri için en uygun değerlendirme hangisidir?', 'Heceyi metafizik bir derinlik ve modern bir şehir duyarlılığıyla buluşturmuştur.', ['Garip hareketinin kurucularından biri olarak ölçüsüz, kafiyesiz serbest şiiri başlatmıştır.', 'İkinci Yeni\'nin kuramcısı olarak anlamsızlık estetiğini savunmuştur.', 'Toplumcu gerçekçi şiirin ilk temsilcisi olmuştur.'], 'Necip Fazıl, Hececiler\'in yüzeysel memleketçiliğini aşarak heceyle derin bir iç dünya ve metafizik kaygı dile getirmiştir.'),
  ('Nazım Hikmet\'in Rus fütürist şair Mayakovski\'den etkilenerek Türk şiirine getirdiği biçim yeniliği hangisidir?', 'Dizeleri basamak basamak bölen merdiven biçimli yazım', ['On dört dizelik, iki dörtlük ve iki üçlükten oluşan sone biçimi', 'Aruzun müstezat kalıbı', 'Üç dizelik haiku biçimi'], 'Nazım, Moskova\'da tanıdığı Mayakovski\'nin etkisiyle dizeleri kırarak basamaklı (merdiven) bir yazım kullanmış, ritmi vurgularla kurmuştur.'),
  ('Nazım Hikmet\'in Mona Lisa tablosunun Louvre\'dan kaçıp Çin\'e gitmesini hayal gücüyle anlattığı 1929 tarihli kitabı hangisidir?', 'Jokond ile Si-Ya-U', ['Benerci Kendini Niçin Öldürdü', 'Gece Gelen Telgraf', 'Sesini Kaybeden Şehir'], 'Jokond ile Si-Ya-U\'da Jokond (Mona Lisa) müzeden kaçarak Şanghay\'a gider ve devrimci Si-Ya-U ile tanışır.'),
  ('Nazım Hikmet\'in Hindistan\'da geçen ve bir devrimcinin intiharını sorgulayan 1932 tarihli uzun şiiri hangisidir?', 'Benerci Kendini Niçin Öldürdü', ['Jokond ile Si-Ya-U', 'Taranta Babu\'ya Mektuplar ve Portreler', 'Kuvâyi Milliye'], 'Benerci Kendini Niçin Öldürdü, sömürge Hindistan\'ında geçen ve Benerci adlı devrimcinin hikâyesini anlatan uzun bir şiirdir.'),
  ('Nazım Hikmet \'Kerem Gibi\' şiirinde \'Ben yanmasam / sen yanmasan / biz yanmasak / nasıl çıkar / karanlıklar / aydınlığa\' derken halk hikâyesindeki Kerem\'i hangi anlamda kullanır?', 'Başkaları için kendini feda eden fedakâr insan', ['Sevgilisinden vazgeçip ilk zorlukta kaçan korkak ve bencil âşık', 'Halkını kandıran zalim bir hükümdar', 'Doğaüstü güçleri olan bir büyücü'], 'Kerem, Aslı uğruna yanan âşıktır; Nazım bu motifi bir davaya adanmış ve karanlığı aydınlatmak için yanan insan anlamına taşır.'),
  ('Nazım Hikmet\'in Hiroşima\'da atom bombasıyla ölen bir çocuğun ağzından yazdığı ve \'Kapıları çalan benim\' diye başlayan şiiri hangi adla bilinir?', 'Kız Çocuğu', ['Salkımsöğüt', 'Davet', 'Hasret'], '\'Kız Çocuğu\' şiirinde Hiroşima\'da yanan küçük bir kız barış için kapı kapı dolaşır; şiir sonradan bestelenmiştir.'),
  ('Nazım Hikmet\'in uzun hapis yıllarının büyük bölümünü geçirdiği ve birçok önemli eserini yazdığı cezaevi hangi şehirdeydi?', 'Bursa', ['Sinop', 'Kayseri', 'Diyarbakır'], 'Nazım 1938\'de mahkûm edildikten sonra en uzun süre Bursa Cezaevinde kalmış, Memleketimden İnsan Manzaraları gibi eserlerini orada yazmıştır.'),
  ('Nazım Hikmet\'in yurt dışına çıktıktan sonra 1951\'de kaybettiği ve ancak 2009\'da yeniden tanınan hak hangisidir?', 'Türk vatandaşlığı', ['Milletvekilliği', 'Üniversite kürsüsü', 'Yayın ruhsatı'], 'Nazım\'ın Türk vatandaşlığı 1951\'de Bakanlar Kurulu kararıyla kaldırılmış, 2009\'da yeniden verilmiştir.'),
  ('Nazım Hikmet\'in tiyatro eserleri arasında yer almayan hangisidir?', 'Köşebaşı', ['Kafatası', 'Ferhat ile Şirin', 'Yusuf ile Menofis'], 'Kafatası, Ferhat ile Şirin ve Yusuf ile Menofis Nazım\'ın oyunlarıdır; Köşebaşı Ahmet Kutsi Tecer\'indir.'),
  ('Nazım Hikmet\'in şiir dili için hangisi en doğru değerlendirmedir?', 'Konuşma dilini, halk türküsünü ve destan söyleyişini serbest şiirde birleştirmiştir.', ['Yalnızca Osmanlıca tamlamalarla ağır bir dil kurmuştur.', 'Sözcükleri anlamından koparıp yalnızca seslerine dayanan soyut ses oyunlarına dönüştürmüştür.', 'Halk diline hiç yer vermeyen salon şiiri yazmıştır.'], 'Nazım, Kuvâyi Milliye ve Memleketimden İnsan Manzaraları\'nda görüldüğü gibi gündelik dili, türkü ve destan geleneğini modern serbest şiirle kaynaştırmıştır.'),
  ('Rıfat Ilgaz\'ın 1944\'te yayımlanan ve toplatılarak şairin yargılanmasına yol açan şiir kitabı hangisidir?', 'Sınıf', ['Yarenlik', 'Karşı', 'Kavel'], 'Sınıf, yoksul öğretmenleri ve emekçileri işleyen şiirleri nedeniyle toplatılmış, Rıfat Ilgaz bu kitap yüzünden kovuşturmaya uğramıştır. Yarenlik onun bir yıl önceki ilk kitabıdır.'),
  ('Enver Gökçe\'nin toplumcu şiirini diğer kuşak arkadaşlarından ayıran en belirgin yön hangisidir?', 'Halk türküsünün ve ağıtın söyleyişini toplumcu içerikle birleştirmesi', ['Divan şiirinin gazel biçimini canlandırmaya çalışması', 'Batı\'daki gerçeküstücü otomatik yazıyı bilinçaltı imgeleriyle birlikte uygulaması', 'Şiirlerini yalnız çocuklar için masal biçiminde yazması'], 'Enver Gökçe, \'Dost Dost İlle Kavga\' gibi şiirlerinde türkü ritmini ve halk deyişlerini toplumsal mücadele temasıyla buluşturmuştur.'),
  ('Aşağıdaki şairlerden hangisi 1940 kuşağı toplumcu gerçekçi şairler arasında sayılmaz?', 'Ziya Osman Saba', ['Ömer Faruk Toprak', 'Cahit Irgat', 'Arif Damar'], 'Ziya Osman Saba, Yedi Meşale\'den gelen ve ev, aile, Tanrı temalarını işleyen bireysel bir şairdir; diğerleri toplumcu kuşaktandır.'),
  ('Ahmed Arif\'in 1943\'te Doğu sınırında sorgusuz öldürülen köylüleri anlattığı uzun şiiri hangisidir?', 'Otuz Üç Kurşun', ['Adiloş Bebenin Ninnisi', 'Kuvâyi Milliye', 'Kavel'], 'Otuz Üç Kurşun, Van-Özalp çevresinde kurşuna dizilen otuz üç köylünün trajedisini destansı bir dille anlatır.'),
  ('Ahmed Arif\'in yazar Leyla Erbil\'e yazdığı mektuplar ölümünden sonra hangi adla kitaplaşmıştır?', 'Leylim Leylim', ['Ziya\'ya Mektuplar', 'Sevda Sözleri', 'Kırmızı Karanfil'], 'Ahmed Arif\'in Leyla Erbil\'e mektupları Leylim Leylim adıyla yayımlanmıştır. Ziya\'ya Mektuplar Cahit Sıtkı\'nın, Kırmızı Karanfil Gülten Akın\'ın kitabıdır.'),
  ('Ahmed Arif\'in şiir dilini kuşağının diğer toplumcu şairlerinden ayıran özellik hangisidir?', 'Doğu Anadolu ağzından sözcüklerle destansı ve lirik bir sesi birleştirmesi', ['Gündelik İstanbul konuşmasını, argoyu ve nükteli espriyi şiirin tam merkezine koyması', 'Ölçüye ve kafiyeye tamamen sırt çevirip düzyazıya yaklaşması', 'Batı mitolojisinden kahramanları şiirin merkezine yerleştirmesi'], 'Ahmed Arif\'in şiiri, Diyarbakır ve çevresinin söyleyişini taşıyan sözcükler, epik bir coşku ve yoğun bir lirizmle tanınır.'),
  ('Garip şairlerinin 1940\'ların başında edebiyat dünyasında tepkiyle karşılanmasının temel nedeni hangisidir?', 'Şiiri sıradan konular ve günlük dille yazarak şiirsellik anlayışını sarsmaları', ['Yalnızca aruzla yazıp hece ölçüsünü küçümsemeleri', 'Siyasi bildirilerle hükümeti ve milletvekillerini açıkça hedef alan şiirler yayımlamaları', 'Şiirlerini Fransızca yayımlayıp Türkçeyi dışlamaları'], 'Nasır, rakı, Süleyman Efendi gibi sıradan konuların ve konuşma dilinin şiire girmesi, o dönemin şiir anlayışına alışık okurları ve eleştirmenleri şaşırtmıştır.'),
  ('Garip şiirinin 1940\'ların sonunda tekdüzeleşmesine ve eleştirilmesine yol açan gelişme hangisidir?', 'Taklitçilerin bu şiiri nükte ve şakadan ibaret bir kalıba indirgemesi', ['Üç şairin de aruza dönerek eski biçimleri canlandırması', 'Devletin bu şiiri okullarda yasaklaması', 'Garip şairlerinin İkinci Yeni\'ye katılması için ortak bildiri yayımlaması'], 'Orhan Veli\'yi kolayca taklit edilebilir sanan pek çok genç şair esprili, yüzeysel şiirler yazmış; bu durum yeni arayışlara, özellikle İkinci Yeni\'ye zemin hazırlamıştır.'),
  ('Orhan Veli\'nin şiir kitaplarının yayım sırası hangi seçenekte doğru verilmiştir?', 'Vazgeçemediğim → Destan Gibi → Yenisi → Karşı', ['Karşı → Yenisi → Destan Gibi → Vazgeçemediğim', 'Destan Gibi → Karşı → Vazgeçemediğim → Yenisi', 'Yenisi → Vazgeçemediğim → Karşı → Destan Gibi'], 'Garip\'ten sonra Vazgeçemediğim (1945), Destan Gibi (1946), Yenisi (1947) ve Karşı (1949) yayımlanmıştır.'),
  ('Orhan Veli\'nin Fransız edebiyatından yaptığı çeviriler arasında özellikle hangi şairin fablları öne çıkar?', 'La Fontaine', ['Victor Hugo', 'Charles Baudelaire', 'Paul Valéry'], 'Orhan Veli La Fontaine\'in masallarını Türkçeye manzum ve akıcı bir dille çevirmiştir.'),
  ('Orhan Veli\'nin bir halk kahramanının fıkralarını manzum olarak yeniden yazdığı çalışma hangisidir?', 'Nasreddin Hoca Hikâyeleri', ['Dede Korkut Kitabı\'ndaki Boylar', 'Keloğlan Masalları', 'Karagöz Muhaveraları'], 'Orhan Veli, Nasreddin Hoca fıkralarını kendi yalın üslubuyla manzum hâle getirmiştir.'),
  ('Orhan Veli\'nin genç yaşta ölümüne yol açan olay hangisidir?', 'Ankara\'da bir çukura düşmesinin ardından gelen beyin kanaması', ['Bir deniz kazasında boğulması', 'Uzun süren verem hastalığı', 'Geçirdiği ani bir kalp krizi'], 'Orhan Veli 1950\'de Ankara\'da belediyenin açtığı bir çukura düşmüş, ardından İstanbul\'da beyin kanamasından ölmüştür.'),
  ('Orhan Veli\'nin şiirini başlangıçtaki Garip çizgisinden ayıran son dönem eğilimi hangisidir?', 'Halk şiiri ve türkü söyleyişinden daha çok yararlanması', ['Aruza dönerek gazel yazması', 'Uzun, kapalı ve mitolojik göndermelerle dolu şiirlere yönelmesi', 'Şiiri bırakıp yalnızca roman yazması'], 'Destan Gibi ve sonraki kitaplarında Orhan Veli halk şiirinin, destan ve türkünün söyleyişinden beslenmiş, şiirine daha toplumsal bir ton katmıştır.'),
  ('Orhan Veli\'nin şiirinde \'şairanelik\' kavramına karşı tutumu en iyi hangi örnekle açıklanır?', 'Ay, gül, bülbül gibi alışılmış şiir imgeleri yerine nasır, rakı, Süleyman Efendi gibi sıradan şeyleri anlatması', ['Sevgiliyi servi boylu, ay yüzlü, hilal kaşlı olarak betimleyen klasik benzetmeleri yeniden canlandırıp yüceltmesi', 'Şiirlerinde Farsça tamlamaları artırarak eski söyleyişi sürdürmesi', 'Her şiirini aynı kafiye düzeniyle kurarak biçimi kutsallaştırması'], 'Orhan Veli \'şairane\' denilen kalıplaşmış güzellikleri reddetmiş, şiire gündelik hayatın sıradan nesnelerini ve insanlarını sokmuştur.'),
  ('Oktay Rifat\'ın 1966\'da yayımladığı ve başlığıyla özgürlüğü somut bir varlık gibi canlandıran şiir kitabı hangisidir?', 'Elleri Var Özgürlüğün', ['Perçemli Sokak ve Âşık Merdiveni', 'Güzelleme', 'Sevda Sözleri'], 'Elleri Var Özgürlüğün (1966) toplumsal duyarlılığın da öne çıktığı bir kitaptır. Sevda Sözleri Cemal Süreya\'nın toplu şiirleridir.'),
  ('Oktay Rifat\'ın meslek hayatı için hangisi doğrudur?', 'Hukuk öğrenimi görmüş ve avukatlık yapmıştır.', ['Askerî okulda okuyup subay olarak emekli olmuştur.', 'Tıp okuyup veteriner hekim olarak çalışmıştır.', 'Mimarlık okuyup Sinan üzerine kitaplar yazmıştır.'], 'Oktay Rifat Ankara Hukuk Fakültesini bitirmiş, avukatlık ve memurluk yapmıştır.'),
  ('Oktay Rifat\'ın şiir serüveni için en doğru sıralama hangisidir?', 'Garip\'in yalın şiiri → imge yoğun, İkinci Yeni\'ye yakın şiir → daha sade ve geleneğe açık son dönem', ['Aruzlu divan şiiri → Garip\'in yalın şiiri → toplumcu destan', 'İkinci Yeni şiiri → Garip\'in yalın şiiri → Hececi memleket şiiri', 'Toplumcu gerçekçi şiir → Yedi Meşale şiiri → Garip\'in yalın şiiri'], 'Oktay Rifat Garip\'le başlamış, Perçemli Sokak ve Âşık Merdiveni\'nde imgeci bir şiire geçmiş, son kitaplarında (Elifli, Çobanıl Şiirler) daha arı ve geleneğe yaslanan bir söyleyişe yönelmiştir.'),
  ('Melih Cevdet Anday\'ın 1946\'da yayımlanan ilk kişisel şiir kitabı hangisidir?', 'Rahatı Kaçan Ağaç', ['Göçebe Denizin Üstünde', 'Telgrafhane ve Yanyana', 'Teknenin Ölümü'], 'Rahatı Kaçan Ağaç (1946) Melih Cevdet\'in Garip\'ten sonraki ilk kitabıdır; Telgrafhane 1952\'de, Yanyana 1956\'da yayımlanmıştır.'),
  ('Melih Cevdet Anday\'ın Mezopotamya\'nın ölümsüzlük arayan kahramanından yola çıkarak yazdığı şiir kitabı hangisidir?', 'Ölümsüzlük Ardında Gılgamış', ['Kolları Bağlı Odysseus ve Teknenin Ölümü', 'Göçebe Denizin Üstünde', 'Âşık Merdiveni'], 'Melih Cevdet bu kitabında Gılgamış destanını zaman, ölüm ve insan üzerine düşünceyle yeniden yorumlar.'),
  ('Melih Cevdet\'in 1970 tarihli \'Göçebe Denizin Üstünde\' adlı uzun şiiri hangi yönelimin ürünüdür?', 'Mitoloji ve felsefeyle zaman ve varoluşu sorgulayan düşünce şiiri', ['Hece ölçüsüyle Anadolu manzaralarını ve yayla hayatını anlatan memleket şiiri', 'Gündelik espriye dayanan, Garip\'in ilk dönemine dönüş', 'Âşık atışmalarını taklit eden doğaçlama bir halk şiiri'], 'Garip\'ten sonra Melih Cevdet şiirini düşünceye, mitlere ve evren-insan ilişkisine açmıştır; Göçebe Denizin Üstünde bu dönemin önemli örneğidir.'),
  ('Melih Cevdet Anday\'ın uzun yıllar sürdürdüğü ve görüşlerini geniş okura ulaştırdığı yazı türü hangisidir?', 'Gazetelerde deneme ve fıkra yazarlığı', ['Radyo için çocuk masalı seslendirmesi', 'Sinema için senaryo yazarlığı ve film yönetmenliği', 'Opera sahnelerinde şancılık'], 'Melih Cevdet, Cumhuriyet gibi gazetelerde uzun yıllar köşe yazıları ve denemeler yazmıştır.'),
  ('Melih Cevdet Anday\'ın şiiri için aşağıdaki yargılardan hangisi en doğrudur?', 'Garip\'in yalınlığından başlayıp mit, kavram ve düşünceyle örülen entelektüel bir şiire ulaşmıştır.', ['Ömür boyu hece ölçüsüyle memleket şiiri yazmış, hiç değişmemiştir.', 'Dinî-tasavvufi bir şiir kurarak İslami duyarlılığı ve metafizik ürpertiyi öne çıkaran bir çizgi izlemiştir.', 'Halk ozanı geleneğinde doğaçlama şiir söylemiştir.'], 'Melih Cevdet\'in şiiri Garip\'in sadeliğinden yola çıkıp düşünce, mitoloji ve zaman sorunsalı üzerine kurulu bir yapıya dönüşmüştür.'),
  ('Garip\'in üç şairinden hangisinin şiirinde Antik Yunan ve Mezopotamya mitlerine göndermeler en belirgin biçimde yer alır?', 'Melih Cevdet Anday', ['Orhan Veli Kanık', 'Oktay Rifat Horozcu', 'Ahmet Kutsi Tecer'], 'Odysseus ve Gılgamış gibi mitik kahramanları şiirinin merkezine alan şair Melih Cevdet\'tir. Tecer Garip şairi değildir.'),
  ('Fazıl Hüsnü Dağlarca\'nın bir çocuğun gözünden Tanrı\'yı ve varlığı sorguladığı 1940 tarihli şiir kitabı hangisidir?', 'Çocuk ve Allah', ['Toprak Ana ve Köylüler', 'Havaya Çizilen Dünya', 'Sebil ve Güvercinler'], 'Çocuk ve Allah (1940), Dağlarca\'nın metafizik sorgulamaları çocuk saflığıyla dile getirdiği ünlü kitabıdır.'),
  ('Fazıl Hüsnü Dağlarca\'nın Anadolu köylüsünün yoksulluğunu ve toprakla bağını işlediği 1950 tarihli kitabı hangisidir?', 'Toprak Ana', ['Çakırın Destanı', 'Çocuk ve Allah', 'Rüzgâr Saati'], 'Toprak Ana, Dağlarca\'nın toplumsal gerçekliği köylünün yaşamı üzerinden işlediği kitabıdır. Rüzgâr Saati Gülten Akın\'ın kitabıdır.'),
  ('Fazıl Hüsnü Dağlarca\'nın 1966\'da yayımladığı ve uzak bir ülkedeki savaşa karşı tavır aldığı şiir kitabı hangisidir?', 'Vietnam Savaşımız', ['Kore Mektupları ve Asya Şiirleri', 'Taranta Babu\'ya Mektuplar', 'Kız Çocuğu'], 'Vietnam Savaşımız, Dağlarca\'nın emperyalizme ve savaşa karşı tutumunu dile getirdiği toplumsal şiirlerdendir.'),
  ('Fazıl Hüsnü Dağlarca\'nın şiire tam olarak yönelmeden önce sürdürdüğü meslek hangisidir?', 'Subaylık', ['Hekimlik', 'Avukatlık', 'Diplomatlık'], 'Dağlarca Harbiye\'yi bitirmiş, uzun yıllar subay olarak çalışmış, 1950\'de ordudan ayrılmıştır.'),
  ('Fazıl Hüsnü Dağlarca\'nın Kurtuluş Savaşı ve Çanakkale gibi tarihî olayları işlediği eserleri, onun şiirinin hangi yönünü gösterir?', 'Destan türünde, millî tarihi coşkuyla anlatan epik yönünü', ['Divan şiirini taklit eden süslü ve klasik yönünü', 'Şehirli bireyin bunalımını ve yalnızlığını anlatan varoluşçu yönünü', 'Mizahi ve hicivli taşlamalara dayanan yönünü'], 'Üç Şehitler Destanı, Çanakkale Destanı gibi kitaplarında Dağlarca millî tarihi epik bir dille yeniden kurmuştur.'),
  ('Fazıl Hüsnü Dağlarca\'nın şiir serüveni için en uygun değerlendirme hangisidir?', 'Hiçbir topluluğa bağlanmadan metafizikten destana, toplumsal şiirden çocuk şiirine geniş bir alanda yazmıştır.', ['Garip topluluğunun dördüncü üyesi olarak ortak kitapta yer almıştır.', 'Yalnızca hece ölçüsüyle aşk şiirleri yazmış, konu çeşitliliğine gitmemiştir.', 'İkinci Yeni\'nin kuramcısı olarak dergi çıkarmış, başka alanda ürün vermemiştir.'], 'Dağlarca topluluk dışı, çok üretken bir şairdir; Çocuk ve Allah\'tan Vietnam Savaşımız\'a uzanan çok geniş bir tematik yelpazesi vardır.'),
  ('Behçet Necatigil\'in 1945\'te yayımlanan ilk şiir kitabı, adını İstanbul\'un tarihî bir alışveriş mekânından alır. Bu kitap hangisidir?', 'Kapalıçarşı', ['Evler ve Odalar', 'Divançe', 'Eski Toprak'], 'Kapalıçarşı (1945) Necatigil\'in ilk kitabıdır; Evler 1953\'te, Divançe 1965\'te, Eski Toprak 1956\'da yayımlanmıştır.'),
  ('Behçet Necatigil\'in ev, aile ve orta hâlli şehirlinin dünyasını yoğun biçimde işlediği 1953 tarihli kitabı hangisidir?', 'Evler', ['Çevre', 'Arada', 'Beyler'], 'Evler, Necatigil\'in \'evler şairi\' olarak anılmasına yol açan temalarının en belirgin görüldüğü kitaptır.'),
  ('Behçet Necatigil şiirinin yanı sıra çevirmen olarak en çok hangi dilden yaptığı çevirilerle tanınır?', 'Almanca', ['Rusça', 'İspanyolca', 'Japonca'], 'Necatigil Almancadan Hesse, Rilke gibi yazarların eserlerini Türkçeye çevirmiştir.'),
  ('Behçet Necatigil\'in ölümünden sonra adına kurulan ve her yıl bir şiir kitabına verilen ödül neyi gösterir?', 'Şiirinin genç kuşaklar için örnek ve ölçüt sayılmasını', ['Yalnızca radyo oyunlarının ödüllendirilmesini', 'Romanlarının sinemaya uyarlanıp geniş kitlelere ulaşmasını', 'Siyasi görüşlerinin bir partiye ilham vermesini'], 'Behçet Necatigil Şiir Ödülü 1980\'den beri verilmektedir; bu, onun şiirimizdeki saygın yerini gösterir.'),
  ('Behçet Necatigil\'in sonraki dönem şiirlerinde artan özellik hangisidir?', 'Sözcük oyunları ve çağrışımlarla yoğunlaşan, daha kapalı bir anlatım', ['Coşkulu hitaplarla dolu kahramanlık destanları', 'Aruzla yazılmış uzun kasideler', 'Tamamen gündelik espriye ve şakaya dayanan yalın ve kısa şiirler'], 'Necatigil ilk kitaplarındaki açık ve yalın anlatımı sonraki kitaplarında yoğun, çağrışımlı ve kapalı bir dile dönüştürmüştür.'),
  ('Cahit Külebi\'nin 1946\'da yayımlanan ilk şiir kitabı hangisidir?', 'Adamın Biri', ['Yeşeren Otlar', 'Süt', 'Rüzgâr ve Anadolu Türküleri'], 'Adamın Biri (1946) Külebi\'nin ilk kitabıdır; Rüzgâr 1949\'da, Yeşeren Otlar 1954\'te, Süt 1965\'te yayımlanmıştır.'),
  ('Cahit Külebi\'nin doğup büyüdüğü ve şiirlerinde sıkça andığı yöre hangisidir?', 'Tokat ve Niksar çevresi', ['Trabzon ve Rize çevresi', 'Konya ve Karaman çevresi', 'Edirne ve Kırklareli çevresi'], 'Külebi 1917\'de Tokat\'ın Niksar ilçesinde doğmuştur; şiirlerinde bu yörenin insanları ve doğası yer alır.'),
  ('Cahit Külebi\'nin Anadolu\'yu anlatışı, Beş Hececiler\'in memleket şiiriyle karşılaştırıldığında hangi farkı gösterir?', 'Turistik bir manzara yerine içeriden, yaşanmış bir duyarlılıkla anlatır.', ['Anadolu\'yu hiç anlatmaz, yalnız İstanbul\'u işler.', 'Aruzu kullanarak Anadolu\'yu divan diliyle anlatır.', 'Anadolu\'yu anlamı kapalı, soyut ve gerçeküstü imgelerle anlatır.'], 'Hececilerin şiirinde Anadolu çoğu zaman dışarıdan bakan bir yolcunun gözüyle görülürken, Külebi oranın insanını içeriden ve sahici biçimde anlatır.'),
  ('Asaf Halet Çelebi\'nin 1942\'de yayımlanan ilk şiir kitabı, tek bir hece gibi duran kısa adıyla dikkat çeker. Bu kitap hangisidir?', 'He', ['Lâmelif', 'Om Mani Padme Hum', 'Elifli'], 'Asaf Halet\'in kitapları sırasıyla He (1942), Lâmelif (1945) ve Om Mani Padme Hum\'dur (1953). Elifli Oktay Rifat\'ın kitabıdır.'),
  ('Asaf Halet Çelebi\'nin bir Budist duasından adını alan 1953 tarihli şiir kitabı hangisidir?', 'Om Mani Padme Hum', ['Lâmelif', 'Sidharta ve Nirvana', 'Ayinler'], 'Om Mani Padme Hum, Tibet Budizmindeki ünlü mantradır; şair Doğu inançlarına duyduğu ilgiyi bu adla yansıtır.'),
  ('Asaf Halet Çelebi\'nin şiirinde sözcüklerin anlamından çok ses değerine, büyü ve dua etkisine yaslanması, sonraki hangi şiir hareketi için öncü sayılmasına yol açmıştır?', 'İkinci Yeni', ['Beş Hececiler', 'Yedi Meşaleciler', 'Millî Edebiyat'], 'Asaf Halet\'in mistik, çağrışımcı ve sesçil şiiri, 1950\'lerde imgeye ve anlam kapalılığına yönelen İkinci Yeni şairlerince bir öncü olarak görülmüştür.'),
  ('Asaf Halet Çelebi\'nin şiiri ile çağdaşı Garip şiiri karşılaştırıldığında hangi karşıtlık öne çıkar?', 'Asaf Halet mistik ve sesçil bir dünyaya yönelirken Garip gündelik ve yalın bir dile yönelmiştir.', ['Asaf Halet hece ölçüsüyle köy şiiri yazarken Garip aruzla gazel yazmıştır.', 'Asaf Halet toplumcu gerçekçi iken Garip metafizik ve dinî bir şiir yazmıştır.', 'İkisi de aynı ortak kitapta yer almış, aralarında fark bulunmamaktadır.'], 'Aynı yıllarda yazan bu iki anlayıştan biri esrarlı, çağrışımcı ve Doğu kaynaklı; diğeri sade, esprili ve günlük hayattan beslenen bir şiir kurmuştur.'),
  ('Bedri Rahmi Eyüboğlu\'nun şiiri ile resmi arasındaki ortak nokta en iyi hangi seçenekte ifade edilir?', 'İkisinde de halk sanatından, motiflerden ve renk coşkusundan beslenmesi', ['İkisinde de yalnız soyut geometrik biçimlere ağırlık vermesi', 'İkisinde de Divan sanatının minyatür kurallarına sadık kalması', 'İkisinde de Batı\'nın klasik akademik kurallarını ve Rönesans ustalarını taklit etmesi'], 'Bedri Rahmi kilim, nakış ve halk motiflerini tuvaline taşıdığı gibi şiirinde de türkü ve halk söyleyişinin renkli dünyasından yararlanmıştır.'),
  ('Bedri Rahmi Eyüboğlu\'nun Mavi Anadolu anlayışının öncülerinden olan kardeşi kimdir?', 'Sabahattin Eyüboğlu', ['Eren Eyüboğlu', 'Ahmet Hamdi Tanpınar', 'Cevat Şakir Kabaağaçlı'], 'Sabahattin Eyüboğlu, Bedri Rahmi\'nin kardeşidir; deneme ve çevirileriyle Mavi Anadolu hümanizminin öncüleri arasında sayılır. Eren Eyüboğlu ise Bedri Rahmi\'nin ressam eşidir.'),
  ('Romanlarıyla tanınan Sabahattin Ali\'nin sağlığında, 1934\'te yayımlanan tek şiir kitabı hangisidir?', 'Dağlar ve Rüzgâr', ['Hasretinden Prangalar Eskittim', 'Sınıf', 'Kapalıçarşı'], 'Sabahattin Ali\'nin sağlığında yayımlanan tek şiir kitabı Dağlar ve Rüzgâr\'dır (1934); halk şiiri söyleyişine yakın, hece ölçülü şiirlerden oluşur.'),
  ('Ney üstadı olarak da tanınan, ikiyüzlülüğü ve toplumsal çürümeyi sert bir dille eleştiren \'Hiç\' ve \'Azâb-ı Mukaddes\' adlı eserlerin şairi kimdir?', 'Neyzen Tevfik', ['Yusuf Ziya Ortaç', 'Orhan Seyfi Orhon', 'Arif Nihat Asya'], 'Neyzen Tevfik Kolaylı, hiciv şiirleri ve ney icracılığıyla tanınır; Hiç ve Azâb-ı Mukaddes onun şiir kitaplarıdır.'),
  ('Abdurrahim Karakoç\'un toplumsal eleştirilerini bir kişiye seslenen mektuplar biçiminde dile getirdiği eseri hangisidir?', 'Hasan\'a Mektuplar', ['Ziya\'ya Mektuplar', 'Leylim Leylim', 'Taranta Babu\'ya Mektuplar'], 'Hasan\'a Mektuplar Abdurrahim Karakoç\'undur. Ziya\'ya Mektuplar Cahit Sıtkı\'nın, Leylim Leylim Ahmed Arif\'in, Taranta Babu\'ya Mektuplar Nazım Hikmet\'in eseridir.'),
  ('Hisar dergisinin 1950\'deki kurucuları arasında yer alan isimler hangi seçenekte doğru verilmiştir?', 'Mehmet Çınarlı, Munis Faik Ozansoy, Gültekin Samanoğlu', ['Cemal Süreya, Turgut Uyar, Edip Cansever', 'Orhan Veli, Oktay Rifat, Melih Cevdet Anday', 'Ataol Behramoğlu, İsmet Özel, Süreyya Berfe'], 'Hisar, Mehmet Çınarlı, Munis Faik Ozansoy, Gültekin Samanoğlu ve İlhan Geçer gibi genç şairlerce kurulmuştur. Diğer seçenekler İkinci Yeni, Garip ve 1960 kuşağına aittir.'),
  ('Hisar dergisinin kurucularından Munis Faik Ozansoy\'un babası olan Beş Hececiler şairi kimdir?', 'Halit Fahri Ozansoy', ['Orhan Seyfi Orhon', 'Ömer Bedrettin Uşaklı', 'Yusuf Ziya Ortaç'], 'Munis Faik Ozansoy, Beş Hececiler\'den Halit Fahri Ozansoy\'un oğludur; aile soyadı da bu bağı gösterir.'),
  ('Aşağıdaki şairlerden hangisi Hisar dergisi çevresinde yetişen şairler arasında sayılır?', 'Yavuz Bülent Bakiler', ['Ece Ayhan', 'Hasan Hüseyin Korkmazgil', 'Ülkü Tamer'], 'Yavuz Bülent Bakiler Hisar çevresinde yetişmiştir. Ece Ayhan ve Ülkü Tamer İkinci Yeni\'ye, Ahmed Arif toplumcu şiire bağlıdır.'),
  ('1950\'li yıllarda Hisar, Mavi ve İkinci Yeni\'nin hemen hemen aynı dönemde ortaya çıkması neyi gösterir?', 'Garip\'in egemenliğinden sonra şiirde farklı yönlere ayrılan arayışları', ['Garip\'in bu yıllarda yeniden güç kazandığını', 'Bütün şairlerin tek bir dergide birleştiğini', 'Şiirin önemini yitirip yerini tamamen roman ve hikâyeye bıraktığını'], 'Garip\'e tepki olarak doğan bu üç hareket gelenekçi, toplumcu-modernist ve imgeci olmak üzere farklı yönlere gitmiştir.'),
  ('Attila İlhan\'ın 1948\'de yayımlanan ilk şiir kitabı hangisidir?', 'Duvar', ['Sisler Bulvarı', 'Yağmur Kaçağı', 'Bela Çiçeği'], 'Duvar (1948) ilk kitabıdır; Sisler Bulvarı 1954\'te, Yağmur Kaçağı 1955\'te, Bela Çiçeği 1962\'de yayımlanmıştır.'),
  ('Attila İlhan\'ın şiir kitaplarından hangisi 1980\'lerde yayımlanmıştır?', 'Elde Var Hüzün', ['Duvar', 'Yasak Sevişmek', 'Sisler Bulvarı'], 'Elde Var Hüzün 1982 tarihlidir. Duvar 1948, Sisler Bulvarı 1954, Yağmur Kaçağı 1955 yılında çıkmıştır.'),
  ('Attila İlhan\'ın 1993 tarihli kitabının adı olan ve ayrılığı aşkın bir parçası sayan ifade hangisidir?', 'Ayrılık Sevdaya Dahil', ['Böyle Bir Sevmek', 'Yasak Sevişmek', 'Korkunun Krallığı Üstüne'], 'Ayrılık Sevdaya Dahil (1993) Attila İlhan\'ın son dönem şiir kitaplarındandır; adı da şiirlerindeki hüzünlü aşk anlayışını özetler.'),
  ('Attila İlhan\'ın şiirlerinin pek çok bestecinin ilgisini çekmesi, şiirinin hangi özelliğiyle açıklanabilir?', 'Hüzünlü aşk temasını ritimli ve ahenkli bir söyleyişle işlemesi', ['Anlamı bilinçli olarak dağıtan, kapalı ve sessiz imgeler kullanması', 'Yalnızca ölçüsüz, düzyazıya yakın uzun anlatılar yazması', 'Matematik ve felsefe terimleriyle örülü soyut bir dil kurması'], 'Attila İlhan\'ın şiiri, aşk ve hüzün temalarını şarkıya yakın, ahenkli bir dille verdiği için kolayca bestelenmiştir.'),
  ('Attila İlhan\'ın şiir dilinde Osmanlıca sözcüklere ve divan şiirinin çağrışımlarına sıkça yer vermesi, onun hangi görüşüyle ilişkilidir?', 'Modern şiiri Doğu\'nun şiir birikimiyle besleme isteği', ['Türkçeyi tamamen yabancı sözcüklerden arındırma isteği', 'Şiiri yalnızca halk ağzıyla yazma isteği', 'Şiirde yalnızca Batı\'yı örnek alma isteği'], 'Attila İlhan Batılılaşmayı eleştiren yazılarında Doğu kültürüne dönüşü önemsemiş; şiirinde de divan ve halk şiirinin birikimini modern biçimle kaynaştırmıştır.'),
  ('Attila İlhan\'ın İkinci Yeni\'ye yönelik tutumu en iyi hangi seçenekte özetlenir?', 'Anlamı ve toplumsal içeriği önemsemediği gerekçesiyle eleştirmiştir.', ['İkinci Yeni\'nin bildirisini yazarak bu hareketin kurucusu ve sözcüsü olmuştur.', 'İkinci Yeni şairleriyle ortak bir şiir kitabı yayımlamıştır.', 'İkinci Yeni\'yi Garip\'ten daha toplumcu bulup övmüştür.'], 'Attila İlhan toplumcu gerçekçi çizgisi gereği İkinci Yeni\'nin anlam kapalılığına ve toplumdan uzaklaşmasına karşı çıkmıştır.'),
  ('İkinci Yeni\'yi Garip ve Yedi Meşale gibi topluluklardan ayıran örgütlenme özelliği hangisidir?', 'Ortak bildiri ya da kitapla çıkmamış, benzer eğilimli şairlerin kendiliğinden oluşturduğu bir hareket olması', ['Kurucularının noter onaylı bir tüzükle dernek kurması', 'Tek bir ortak kitapla doğup hemen dağılması', 'Yalnızca bir şairin yazdığı manifestoya uyan beş kişiden oluşması'], 'İkinci Yeni şairleri ayrı ayrı yazmış; hareketin adını bile bir eleştirmen koymuştur. Garip ve Yedi Meşale ise ortak kitaplarla ortaya çıkmıştır.'),
  ('İkinci Yeni şiirinin kuramsal savunusunu üstlenen, \'Folklor Şiire Düşman\' gibi yazılarıyla halk şiiri taklitçiliğine karşı çıkan şair kimdir?', 'Cemal Süreya', ['Ece Ayhan', 'Edip Cansever', 'Turgut Uyar'], 'Cemal Süreya, İkinci Yeni\'nin sözcüsü ve kuramcısı olarak dergilerde şiir yazıları yazmış; folklorcu şiire karşı çıkmıştır.'),
  ('İkinci Yeni\'nin 1950\'lerde ortaya çıkmasını hazırlayan etkenler arasında hangisi gösterilemez?', 'Hececilerin memleket şiirinin o yıllarda en güçlü dönemini yaşaması', ['Garip şiirinin taklitçilerle tekdüzeleşmesi', 'Toplumcu şiirin siyasi baskılarla sesini yitirmesi', 'Batı\'daki gerçeküstücü ve modern şiirin çeviriler yoluyla tanınması'], '1950\'lerde Hececilerin memleketçi şiiri güçlü değil, gerilemiş durumdaydı; diğer üç etken İkinci Yeni\'nin doğuşunda rol oynamıştır.'),
  ('1950\'lerin siyasi ortamında toplumcu şiire yönelik baskıların İkinci Yeni şiirine yansıması nasıl yorumlanabilir?', 'Şairlerin doğrudan söylem yerine bireyin iç dünyasına ve kapalı imgelere yönelmesi', ['Şairlerin tamamının açıkça siyasi bildiri şiirleri yazması', 'Şiirin yerini tamamen tiyatronun alması', 'Şairlerin aruza dönerek kasideler yazması'], 'Açık toplumsal söylemin riskli olduğu bu dönemde İkinci Yeni şairleri bireyin yabancılaşmasına ve dolaylı, imgeli bir anlatıma yönelmiştir.'),
  ('Garip ile İkinci Yeni\'nin hedef okur konusundaki farkı nasıl özetlenebilir?', 'Garip geniş halk kitlesine seslenirken İkinci Yeni şiir birikimi olan okuru hedefler.', ['Garip yalnızca başka şairlere, İkinci Yeni ise yalnızca okul çağındaki çocuklara seslenir.', 'Garip saray çevresine, İkinci Yeni köylülere seslenir.', 'İkisi de okuru önemsemez, yalnız eleştirmenlere seslenir.'], 'Garip önsözü kalabalığın zevkini savunurken İkinci Yeni\'nin kapalı ve imgeli şiiri daha seçkin, emek veren bir okur gerektirir.'),
  ('İkinci Yeni şiirinde büyük şehir, yalnızlık ve yabancılaşma temalarının öne çıkması hangi gelişmeyle ilişkilendirilir?', 'Hızlı kentleşme ve bireyin kalabalık içinde kendine yabancılaşması', ['Köy enstitülerinin kurulması ve köy hayatının şehre göre yükselişe geçmesi', 'Osmanlı saray kültürünün yeniden canlanması', 'Kurtuluş Savaşı cephelerinin şiire taşınması'], '1950\'lerde hızlanan kentleşme ve modern yaşamın yarattığı yalnızlık, İkinci Yeni şairlerinin bireyi şehirde yabancılaşmış olarak görmesine yol açmıştır.'),
  ('İkinci Yeni\'nin Türk şiirine kalıcı katkısı olarak en çok hangisi gösterilir?', 'Şiir dilinin olanaklarını genişletip imgeyi şiirin merkezine yerleştirmesi', ['Hece ölçüsünü yeniden şiirin tek ölçüsü hâline getirmesi', 'Şiiri tamamen siyasal propagandaya ve slogan tekrarına dönüştürmesi', 'Divan nazım biçimlerini okullarda zorunlu kılması'], 'İkinci Yeni\'nin dili zorlayan, imge yoğun şiiri kendisinden sonraki kuşakların şiir dilini derinden etkilemiştir.'),
  ('Cemal Süreya\'nın doğduğu yer hangisidir?', 'Erzincan\'ın Pülümür ilçesi', ['Trabzon\'un Of ilçesi', 'Tokat\'ın Niksar ilçesi', 'İzmir\'in Menemen ilçesi'], 'Cemal Süreya 1931\'de Pülümür\'de doğmuştur. Niksar Cahit Külebi\'nin, Menemen Attila İlhan\'ın doğum yeridir.'),
  ('Cemal Süreya\'nın şiir dilinin ayırıcı özelliği hangisidir?', 'Beklenmedik sözcük birleşimleri, ironi ve şaşırtıcı bir sözdizimi', ['Divan şiirindeki kalıp benzetmeleri olduğu gibi kullanması', 'Yalnız Anadolu ağzından derlenmiş sözcüklerle yazması', 'Uzun ve olaylı manzum hikâyelerle tarihî kahramanlıkları anlatması'], 'Cemal Süreya dili oyunlu ve ironik kullanır; sözcükleri beklenmedik biçimlerde yan yana getirerek taze imgeler kurar.'),
  ('Turgut Uyar\'ın doğduğu şehir ve şiire başlamadan önceki mesleği hangi seçenekte doğru verilmiştir?', 'Ankara; subay', ['İstanbul; antikacı', 'Erzincan; maliye müfettişi', 'Trabzon; avukat'], 'Turgut Uyar 1927\'de Ankara\'da doğmuş, askerî okulu bitirip uzun süre subay olarak çalışmıştır.'),
  ('Turgut Uyar\'ın İkinci Yeni\'ye geçişini gösteren ve adındaki coğrafi imgeyle düşlenen bir ülkeyi çağrıştıran 1959 tarihli kitabı hangisidir?', 'Dünyanın En Güzel Arabistanı', ['Kayayı Delen İncir ve Divan', 'Arz-ı Hâl', 'Türkiyem'], 'Dünyanın En Güzel Arabistanı (1959), Uyar\'ın imge yoğun ve kapalı şiire geçtiği kitaptır.'),
  ('Turgut Uyar\'ın 1970\'te yayımlanan ve gazel gibi geleneksel biçimleri modern bir duyarlılıkla denediği kitabı hangisidir?', 'Divan', ['Divançe', 'Gazeller ve Rubailer', 'Eski Şiirin Rüzgârıyla'], 'Turgut Uyar Divan adlı kitabında aruz ve gazel biçimlerini yeniden yorumlamıştır. Divançe Necatigil\'in kitabıdır.'),
  ('Turgut Uyar\'ın bütün şiirlerinin toplandığı kitabın adı nedir?', 'Büyük Saat', ['Sevda Sözleri', 'Çile', 'Kendi Gök Kubbemiz'], 'Turgut Uyar\'ın toplu şiirleri Büyük Saat adıyla yayımlanmıştır. Sevda Sözleri Cemal Süreya\'nın, Çile Necip Fazıl\'ın toplu şiirleridir.'),
  ('Turgut Uyar\'ın şiir yolculuğu en iyi hangi seçenekte özetlenir?', 'Hece ve memleket şiirinden İkinci Yeni\'nin imgeci şiirine, oradan geleneği de kucaklayan bir şiire ulaşmıştır.', ['Aruzla başlayıp Garip\'e geçmiş, sonra şiiri bırakmıştır.', 'Hiç değişmeden ömrü boyunca aynı türküsel şiiri yazmıştır.', 'Toplumcu gerçekçi destanlarla başlayıp yalnız çocuk şiirine yönelmiştir.'], 'Arz-ı Hâl ve Türkiyem\'in hece şiirinden Dünyanın En Güzel Arabistanı\'nın imgeciliğine, Divan\'daki gelenek denemelerine uzanan bir gelişim gösterir.'),
  ('Turgut Uyar\'ın eşi olan ve öykü, çeviri ve günlükleriyle tanınan yazar kimdir?', 'Tomris Uyar', ['Adalet Ağaoğlu', 'Sevim Burak', 'Füruzan'], 'Tomris Uyar, Turgut Uyar\'ın eşidir; öyküleri ve çevirileriyle tanınır.'),
  ('Edip Cansever\'in geçimini sağlamak için uzun yıllar Kapalıçarşı\'da sürdürdüğü iş hangisidir?', 'Antikacılık', ['Kitapçılık', 'Kuyumculuk', 'Halı tüccarlığı'], 'Edip Cansever, şiirlerini yazarken Kapalıçarşı\'daki antika dükkânını işletmiştir.'),
  ('Edip Cansever\'in \'Nerde Antigone\', \'Çağrılmayan Yakup\' ve \'Ben Ruhi Bey Nasılım\' gibi kitaplarında belirgin olan anlatım özelliği hangisidir?', 'Kişiler konuşturularak tiyatroya yaklaşan dramatik bir yapı kurulması', ['Divan şiirinin kaside biçiminin aynen uygulanması', 'Olayların yalnızca halk destanı kalıbıyla, koşma biçiminde anlatılması', 'Şiirin çocuklar için masal tekerlemesine dönüştürülmesi'], 'Cansever şiirine kişiler, sesler ve monologlar katarak şiirle tiyatroyu birleştiren bir yapı geliştirmiştir.'),
  ('Ece Ayhan\'ın 1959\'da yayımlanan ilk şiir kitabı hangisidir?', 'Kınar Hanımın Denizleri', ['Bakışsız Bir Kedi Kara', 'Ortodoksluklar', 'Zambaklı Padişah'], 'Kınar Hanımın Denizleri (1959) ilk kitabıdır; Bakışsız Bir Kedi Kara 1965\'te, Ortodoksluklar 1968\'de yayımlanmıştır.'),
  ('Ece Ayhan\'ın şiiri için en uygun değerlendirme hangisidir?', 'Tarihsel ve toplumsal göndermeleri yoğun, en kapalı İkinci Yeni şiirlerinden biridir.', ['Garip\'in en yalın ve esprili örneklerinden biridir.', 'Hece ölçüsüyle yazılmış memleketçi bir şiirdir.', 'Divan şiirinin kurallarına tam uyan bir klasik şiirdir.'], 'Ece Ayhan\'ın şiiri sözdizimi kırılmış, göndermeleri çözülmesi güç ve son derece kapalı bir yapıya sahiptir.'),
  ('İlhan Berk\'in 1952\'de yayımlanan ve Nazım Hikmet etkisinde toplumcu, coşkulu bir söyleyiş taşıyan kitabı hangisidir?', 'Günaydın Yeryüzü', ['Mısır Kalyonu', 'Âşıklar Yolu ve Otağ', 'Galile Denizi'], 'Günaydın Yeryüzü, İlhan Berk\'in İkinci Yeni öncesindeki toplumcu dönemini temsil eder.'),
  ('İlhan Berk\'in doğduğu ve yaşamının son yıllarını geçirdiği yerler hangi seçenekte doğru verilmiştir?', 'Manisa\'da doğmuş, Bodrum\'da ölmüştür.', ['Bursa\'da doğmuş, Ankara\'da ölmüştür.', 'İzmir\'de doğmuş, Paris\'te ölmüştür.', 'Sinop\'ta doğmuş, İstanbul\'da ölmüştür.'], 'İlhan Berk 1918\'de Manisa\'da doğmuş, 2008\'de Bodrum\'da hayatını kaybetmiştir.'),
  ('Sezai Karakoç\'un 1959\'da yayımlanan ilk şiir kitabı hangisidir?', 'Körfez', ['Şahdamar', 'Gül Muştusu', 'Hızırla Kırk Saat'], 'Körfez (1959) ilk kitabıdır; Şahdamar 1962\'de, Hızırla Kırk Saat 1968\'de, Gül Muştusu 1969\'da yayımlanmıştır.'),
  ('Sezai Karakoç\'un ölümsüzlük ve bilgelikle özdeşleşen bir figürle yaptığı yolculuğu konu alan uzun şiiri hangisidir?', 'Hızırla Kırk Saat', ['Taha\'nın Kitabı', 'Körfez', 'Zamana Adanmış Sözler'], 'Hızırla Kırk Saat\'te şair, Hızır ile birlikte zamanın ve medeniyetin içinden geçen manevi bir yolculuğa çıkar.'),
  ('Sezai Karakoç\'un şiiri İkinci Yeni\'nin diğer şairlerinden hangi yönüyle ayrılır?', 'İmgeci ve modern dili İslami bir medeniyet tasavvuru ve metafizik bir bakışla birleştirmesiyle', ['Ölçüsüz yazmayı reddedip yalnız aruzla gazel yazmasıyla', 'Sınıf mücadelesini öne çıkaran toplumcu bir şiir yazmasıyla', 'Garip\'in esprili ve gündelik söyleyişini sürdürmesiyle'], 'Karakoç İkinci Yeni\'nin imge yoğun dilini kullanmış, ancak bu dili kendine özgü bir inanç ve medeniyet düşüncesinin taşıyıcısı yapmıştır.'),
  ('Cahit Zarifoğlu\'nun 1967\'de yayımlanan ilk şiir kitabı hangisidir?', 'İşaret Çocukları', ['Menziller', 'Korku ve Yakarış', 'Yedi Güzel Adam'], 'İşaret Çocukları (1967) ilk kitabıdır; Yedi Güzel Adam 1973\'te, Menziller 1977\'de, Korku ve Yakarış 1985\'te yayımlanmıştır.'),
  ('Cahit Zarifoğlu\'nun 1973 tarihli şiir kitabının adı, sonradan Kahramanmaraş kökenli bir şair ve yazar çevresini anmak için de kullanılmıştır. Bu ad hangisidir?', 'Yedi Güzel Adam', ['Yedi Meşale', 'Yedi Uyurlar', 'Yedi Kardeş Dağları'], 'Zarifoğlu\'nun Yedi Güzel Adam kitabının adı, Sezai Karakoç\'tan Nuri Pakdil\'e uzanan bir yazar çevresine de verilmiştir. Yedi Meşale 1928 topluluğudur.'),
  ('Cahit Zarifoğlu\'nun kurucuları arasında bulunduğu ve 1976\'da yayımlanmaya başlayan dergi hangisidir?', 'Mavera', ['Mavi', 'Papirüs', 'Yeni Dergi'], 'Mavera, 1976\'da Ankara\'da çıkmaya başlamış; Zarifoğlu ve Erdem Bayazıt gibi İslami duyarlılıklı şairleri bir araya getirmiştir.'),
  ('Cahit Zarifoğlu\'nun şiir dili için en uygun nitelik hangisidir?', 'İkinci Yeni\'den aldığı yoğun imgeleri İslami ve mistik bir duyarlılıkla birleştirmesi', ['Hececilerin memleket manzaralarını aynen sürdürmesi', 'Garip\'in espriye dayalı yalın söyleyişini benimsemesi', 'Toplumcu gerçekçi sloganlarla işçi hareketini anlatması'], 'Zarifoğlu, Sezai Karakoç çizgisinde, imgeci modern şiiri inanç merkezli bir dünya görüşüyle kaynaştırmıştır.'),
  ('1960\'lardan sonra İslami duyarlılıkla yazan Sezai Karakoç, Cahit Zarifoğlu ve Erdem Bayazıt\'ın şiiri, Necip Fazıl\'ın şiiriyle karşılaştırıldığında hangi fark öne çıkar?', 'Hece ve kafiye yerine serbest ve imge yoğun modern bir dil kullanmaları', ['Dinî temaları tamamen bırakıp toplumcu şiire geçmeleri', 'Aruzla yazarak divan şiirinin biçimlerini sürdürmeleri', 'Garip\'in ölçü ve kafiye karşıtı önsözünü bildiri olarak benimsemeleri'], 'Necip Fazıl inanç şiirini hece ve sıkı kafiye ile yazarken sonraki kuşak İkinci Yeni\'nin serbest, imgeci dilini kullanmıştır.'),
  ('Ataol Behramoğlu\'nun çevirmen olarak en çok ürün verdiği edebiyat hangisidir?', 'Rus edebiyatı', ['Japon edebiyatı', 'İspanyol edebiyatı', 'Arap edebiyatı'], 'Behramoğlu Puşkin, Lermontov ve Çehov gibi Rus yazarlarını çevirmiş, Rus şiiri antolojisi hazırlamıştır.'),
  ('İsmet Özel\'in 1969 tarihli kitabı, adıyla da toplumcu dönemin başkaldırı ruhunu yansıtır. Bu kitap hangisidir?', 'Evet İsyan', ['Celladıma Gülümserken', 'Erbain', 'Cinayetler Kitabı'], 'Evet İsyan (1969) İsmet Özel\'in toplumcu döneminin kitabıdır; Celladıma Gülümserken (1984) İslami dönemine aittir. Erbain toplu şiirleridir.'),
  ('İsmet Özel\'in kırk yıllık şiir birikimini topladığı ve adı \'kırk\' anlamına gelen tasavvufi bir terimden gelen kitabı hangisidir?', 'Erbain', ['Çile', 'Sevda Sözleri', 'Büyük Saat'], 'Erbain, Arapçada kırk demektir ve tasavvufta kırk günlük inzivayı anlatır; İsmet Özel toplu şiirlerini bu adla yayımlamıştır.'),
  ('Gülten Akın\'ın 1956\'da yayımlanan ilk şiir kitabı hangisidir?', 'Rüzgâr Saati', ['Kestim Kara Saçlarımı', 'Kırmızı Karanfil', 'Seyran'], 'Rüzgâr Saati (1956) ilk kitabıdır; Kestim Kara Saçlarımı 1960\'ta, Kırmızı Karanfil 1971\'de, Seyran 1979\'da yayımlanmıştır.'),
  ('Gülten Akın\'ın 1960\'ta yayımlanan ve kadının kendi kararını veren bir birey olarak ortaya çıkışını simgeleyen bir eylemi anlatan kitap adı hangisidir?', 'Kestim Kara Saçlarımı', ['Sevda Kalıcıdır', 'Ağıtlar ve Türküler', 'İlahiler'], 'Kestim Kara Saçlarımı, kadın kimliğinin ve bağımsızlık isteğinin dile getirildiği şiirleriyle Gülten Akın\'ın önemli kitaplarındandır.'),
  ('Gülten Akın\'ın Anadolu\'yu yakından tanıyıp şiirine halk söyleyişini katmasında hangi yaşam deneyimi etkili olmuştur?', 'Kaymakam olan eşiyle birlikte uzun yıllar Anadolu\'nun çeşitli ilçelerinde yaşaması', ['Gençliğini Paris\'te sürgünde geçirmesi', 'Kapalıçarşı\'da antikacılık yapması', 'Subay olarak sınır karakollarında görev yapması'], 'Gülten Akın eşinin görevi nedeniyle Anadolu ilçelerinde yaşamış; bu deneyim Ağıtlar ve Türküler gibi kitaplarında halk söyleyişine yönelmesini beslemiştir.'),
  ('Gülten Akın\'ın şiir yolculuğu için en doğru değerlendirme hangisidir?', 'Bireysel ve İkinci Yeni\'ye yakın bir başlangıçtan toplumsal ve halk söyleyişine açık bir şiire uzanmıştır.', ['Yalnızca hece ölçüsüyle aşk şiirleri yazmış, hiç değişmemiştir.', 'Garip\'in önsözünü yazarak bu hareketi başlatmıştır.', 'Divan şiirine dönüp yalnız gazel yazmıştır.'], 'Gülten Akın ilk kitaplarında bireysel ve imgeci bir şiir yazmış, 1970\'lerden itibaren ağıt, türkü ve destan biçimleriyle toplumsal konulara yönelmiştir.'),
  ('Can Yücel\'in hayatının son yıllarını geçirdiği ve adıyla özdeşleşen Muğla ilçesi hangisidir?', 'Datça', ['Bodrum', 'Marmaris', 'Fethiye'], 'Can Yücel uzun yıllar Datça\'da yaşamış ve orada gömülmüştür. Bodrum ise İlhan Berk ve Halikarnas Balıkçısı ile anılır.'),
  ('Hilmi Yavuz\'un 1975 tarihli bir kitabı, Nazım Hikmet\'in 1936\'da destanını yazdığı tarihî kişiyi konu alır. Bu kitap hangisidir?', 'Bedreddin Üzerine Şiirler', ['Doğu Şiirleri', 'Bakış Kuşu', 'Zaman Şiirleri'], 'Hilmi Yavuz, Şeyh Bedreddin\'i kendi bakışıyla yeniden şiirleştirmiştir; Nazım\'ın destanından farklı olarak tasavvufi ve düşünsel bir yorum öne çıkar.'),
  ('2 Temmuz 1993\'te Sivas\'ta Madımak Oteli\'nde çıkarılan yangında hayatını kaybeden şairler hangi seçenekte birlikte verilmiştir?', 'Metin Altıok ve Behçet Aysan', ['Ahmed Arif ve Enver Gökçe', 'Cemal Süreya ve Turgut Uyar', 'Gülten Akın ve Can Yücel'], 'Metin Altıok ve Behçet Aysan, Pir Sultan Abdal Kültür Şenliği için Sivas\'ta bulundukları sırada Madımak Oteli yangınında ölmüştür.'),
  ('Genç yaşta ölen Nilgün Marmara\'nın şiirleri ölümünden sonra 1988\'de hangi adla kitaplaştırılmıştır?', 'Daktiloya Çekilmiş Şiirler', ['Grapon Kâğıtları', 'Ah\'lar Ağacı', 'Pulbiber Mahallesi'], 'Nilgün Marmara\'nın şiirleri Daktiloya Çekilmiş Şiirler adıyla yayımlanmıştır. Diğer üç kitap Didem Madak\'ındır.'),
  ('Didem Madak\'ın kitaplarının yayım sırası hangi seçenekte doğru verilmiştir?', 'Grapon Kâğıtları → Ah\'lar Ağacı → Pulbiber Mahallesi', ['Pulbiber Mahallesi → Grapon Kâğıtları → Ah\'lar Ağacı', 'Ah\'lar Ağacı → Pulbiber Mahallesi → Grapon Kâğıtları', 'Grapon Kâğıtları → Pulbiber Mahallesi → Ah\'lar Ağacı'], 'Grapon Kâğıtları 2000\'de, Ah\'lar Ağacı 2002\'de, Pulbiber Mahallesi 2007\'de yayımlanmıştır.'),
  ('12 Eylül 1980 sonrasında yazan genç şairlerin şiirinde 1970\'lerin toplumcu şiirine göre hangi eğilim belirginleşmiştir?', 'Bireyin iç dünyasına, mistik ve metafizik arayışlara ve dilin kendisine yönelme', ['Sloganlı ve eylemci bir siyasal şiirin güçlenmesi', 'Hece ölçüsüyle memleket manzaralarının yeniden yaygınlaşması', 'Şiirin tamamen terk edilip yerini halk hikâyelerine bırakması'], 'Darbe sonrası ortamda toplumcu söylem geri çekilmiş; 1980 kuşağı şairleri bireysel, mistik ve dil merkezli arayışlara yönelmiştir.'),
  ('Nilgün Marmara ve Didem Madak\'ın şiirleri karşılaştırıldığında ikisinde ortak olan nedir?', 'Kadın öznenin acı, yalnızlık ve ölüm duygusunu kendine özgü bir sesle dile getirmesi', ['İkisinin de hece ölçüsüyle kahramanlık destanı yazması', 'İkisinin de Garip topluluğunun ortak kitabında yer alması', 'İkisinin de yalnız çocuk şiiri yazmış olması'], 'İki şair de erken yaşta ölmüş; şiirlerinde kadın deneyimi, yalnızlık ve ölüm temalarını yoğun bir öznellikle işlemiştir.'),
  ('1949\'da Hüsamettin Bozok\'un çıkarmaya başladığı ve uzun yıllar yayımlanan, adını İstanbul\'un tepelerinden alan edebiyat dergisi hangisidir?', 'Yeditepe', ['Yedi Meşale', 'Hisar Dergisi', 'Pazar Postası Eki'], 'Yeditepe, Hüsamettin Bozok yönetiminde yıllarca çıkmış; dergi bir de şiir ödülü vermiştir.'),
  ('Türk Dil Kurumunun 1951\'den beri yayımladığı ve pek çok şairin şiirlerine yer veren dergi hangisidir?', 'Türk Dili', ['Türk Yurdu', 'Türk Sazı', 'Türk Kültürü'], 'Türk Dili, TDK\'nin aylık dil ve edebiyat dergisidir. Türk Sazı ise Mehmet Emin Yurdakul\'un bir şiir kitabıdır.'),
  ('Halkevlerinin 1933\'te yayımlamaya başladığı ve Cumhuriyet\'in kültür politikasını yansıtan merkezî dergi hangisidir?', 'Ülkü', ['Varlık', 'Hisar', 'Dergâh'], 'Ülkü, Halkevlerinin yayın organı olarak halk kültürü, edebiyat ve fikir yazılarına yer vermiştir. Dergâh 1921\'de çıkmıştır.'),
  ('Cemal Süreya\'nın çıkardığı Papirüs ile Sezai Karakoç\'un çıkardığı Diriliş karşılaştırıldığında hangi sonuca ulaşılır?', 'İkinci Yeni\'den gelen iki şairin farklı dünya görüşlerini yansıtan dergiler kurduğu', ['İkisinin de Garip\'in yayın organı olduğu', 'İkisinin de 1928\'de aynı yıl kapatıldığı', 'İkisinin de yalnızca çeviri şiire yer verdiği'], 'Her iki şair de İkinci Yeni içinde değerlendirilir; ancak Papirüs modernist bir edebiyat, Diriliş ise İslami bir medeniyet düşüncesi etrafında şekillenmiştir.'),
  ('Cumhuriyet döneminde edebiyat dergilerinin şiir hareketlerinin doğuşundaki rolü için en uygun yargı hangisidir?', 'Yeni şiir anlayışları çoğu zaman bir dergi çevresinde toplanıp tartışılarak biçimlenmiştir.', ['Dergiler şiirle ilgilenmemiş, yalnız siyaset haberleri yayımlamıştır.', 'Bütün şiir hareketleri devletin çıkardığı tek bir dergide doğmuştur.', 'Dergiler yalnızca eski divan şiirlerini yeniden basmıştır.'], 'Meşale, Varlık, Yaprak, Mavi, Hisar, Pazar Postası, Papirüs ve Diriliş gibi dergiler farklı şiir anlayışlarının yuvası olmuştur.'),
  ('Aşağıdaki dergi ve kurucu eşleştirmelerinden hangisi yanlıştır?', 'Yeditepe – Yaşar Nabi Nayır', ['Varlık – Yaşar Nabi Nayır', 'Ağaç – Necip Fazıl Kısakürek', 'Papirüs – Cemal Süreya'], 'Yeditepe\'yi Hüsamettin Bozok çıkarmıştır; Yaşar Nabi Varlık\'ın kurucusudur. Diğer eşleştirmeler doğrudur.'),
  ('Aşağıdaki dergilerin ilk yayımlanma yıllarına göre sıralanışı hangisinde doğrudur?', 'Varlık → Yaprak → Papirüs', ['Papirüs → Varlık → Yaprak', 'Yaprak → Papirüs → Varlık', 'Varlık → Papirüs → Yaprak'], 'Varlık 1933\'te, Orhan Veli\'nin Yaprak\'ı 1949\'da, Cemal Süreya\'nın Papirüs\'ü 1966\'da yayımlanmaya başlamıştır.'),
  ('Aşağıdaki olayların kronolojik sırası hangi seçenekte doğru verilmiştir?', 'Yedi Meşale\'nin çıkışı → Garip\'in yayımlanması → Hisar\'ın kuruluşu → İkinci Yeni adının konması', ['Garip\'in yayımlanması → Yedi Meşale\'nin çıkışı → İkinci Yeni adının konması → Hisar\'ın kuruluşu', 'Hisar\'ın kuruluşu → Garip\'in yayımlanması → Yedi Meşale\'nin çıkışı → İkinci Yeni adının konması', 'Yedi Meşale\'nin çıkışı → Hisar\'ın kuruluşu → Garip\'in yayımlanması → İkinci Yeni adının konması'], 'Yedi Meşale 1928, Garip 1941, Hisar 1950, İkinci Yeni adlandırması 1956\'dır.'),
  ('Aşağıdakilerden hangisinde, şiirin yanında meslek olarak subaylık da yapmış iki şair birlikte verilmiştir?', 'Fazıl Hüsnü Dağlarca ve Turgut Uyar', ['Edip Cansever ve Cemal Süreya', 'Behçet Necatigil ve Ahmed Arif', 'Oktay Rifat ve Ece Ayhan'], 'Dağlarca ve Turgut Uyar askerî okulu bitirip subay olarak çalışmıştır. Cansever antikacı, Süreya maliyeci, Necatigil öğretmen, Oktay Rifat avukattır.'),
  ('Cumhuriyet döneminde serbest şiirin yaygınlaşmasına katkı yapan iki önemli adım hangi seçenekte doğru verilmiştir?', 'Nazım Hikmet\'in 1929\'daki 835 Satır\'ı ve 1941\'de Garip\'in yayımlanması', ['Yedi Meşale\'nin 1928\'de aruzu zorunlu kılması ve Hisar\'ın kurulması', 'Beş Hececiler\'in 1917\'deki bildirisi ve Dergâh\'ın çıkışı', 'Tanzimat\'ta Şinasi\'nin Tercüme-i Manzume\'si ve Servet-i Fünun\'un kapanması'], 'Nazım serbest şiiri toplumcu bir içerikle, Garip ise gündelik dil ve sıradan konularla yaygınlaştırmıştır.'),
  ('Turgut Uyar\'ın Divan\'ı, Behçet Necatigil\'in Divançe\'si ve Hilmi Yavuz\'un Doğu Şiirleri gibi eserlerin ortak yönü hangisidir?', 'Eski şiirin biçim ve imgelerini modern şiir içinde yeniden yorumlamaları', ['Hece ölçüsüyle yazılmış memleket şiirleri olmaları', 'Garip önsözünü şiir biçiminde yeniden yazmaları', 'Yalnızca çocuklar için yazılmış tekerlemeler olmaları'], 'Bu kitaplar, modern şairlerin divan ve tasavvuf geleneğiyle yeniden ve yaratıcı bir ilişki kurduğunu gösterir.'),
  ('Cumhuriyet dönemi şiirinde ölçü kullanımının genel seyri için en doğru özet hangisidir?', 'Heceden serbest ölçüye geçiş ağır basmış, aruz ve hece bazı şairlerde yaşamayı sürdürmüştür.', ['Aruz tamamen ortadan kalkmış, serbest ölçü hiç kullanılmamıştır.', 'Serbest ölçü 1920\'lerde yasaklanmış, yalnız hece kullanılmıştır.', 'Bütün şairler ömür boyu aruzla yazmış, hece hiç benimsenmemiştir.'], 'Hece 1920-30\'larda egemenken Nazım ve Garip\'le serbest ölçü yaygınlaşmış; Yahya Kemal gibi aruzcular ve Necip Fazıl gibi hececiler de kendi çizgilerini sürdürmüştür.'),
  ('Ahmet Haşim\'in \'saf şiir\' anlayışını Cumhuriyet döneminde sürdüren şairler hangi seçenekte birlikte verilmiştir?', 'Ahmet Hamdi Tanpınar, Ahmet Muhip Dıranas, Cahit Sıtkı Tarancı', ['Orhan Veli, Oktay Rifat, Melih Cevdet Anday', 'Ahmed Arif, Enver Gökçe, Rıfat Ilgaz', 'Ataol Behramoğlu, İsmet Özel, Süreyya Berfe'], 'Bu şairler şiirde musiki, imge ve bireysel duyarlılığı öne çıkararak öz (saf) şiir çizgisinde yazmıştır. Diğer seçenekler Garip, 1940 toplumcuları ve 1960 kuşağıdır.'),
  ('Garip ile toplumcu gerçekçi şiir arasındaki temel fark hangisidir?', 'Garip sıradan insanı ideolojiden uzak bir ironiyle anlatırken toplumcu şiir onu sınıf bilinci içinde ele alır.', ['Garip hece ölçüsüyle, toplumcu şiir yalnız aruzla yazılmıştır.', 'Garip Anadolu\'yu, toplumcu şiir yalnız İstanbul\'u anlatmıştır.', 'Garip kahramanlık destanları, toplumcu şiir aşk gazelleri yazmıştır.'], 'Garip\'in Süleyman Efendi\'si nasırından şikâyet eden sıradan biridir; toplumcu şiirde ise emekçi sömürüye karşı mücadele eden bir öznedir.'),
  ('\'Bugün pazar. / Bugün beni ilk defa güneşe çıkardılar\' dizeleriyle başlayan Nazım Hikmet şiiri, şairin hangi yaşam deneyimini yansıtır?', 'Cezaevinde uzun süre dış dünyadan yoksun kalışını', ['Moskova\'da üniversitede ders verişini', 'Anadolu\'da öğretmenlik yaptığı yılları', 'Çocukluğunda Selanik\'te ailesiyle geçirdiği uzun yaz tatillerini'], 'Şiirde gökyüzünü uzun süre sonra ilk kez gören bir mahkûmun şaşkınlığı ve sevinci anlatılır; Nazım\'ın hapis yıllarından doğmuştur.'),
  ('Nazım Hikmet\'in Ferhat ile Şirin oyununda halk hikâyesindeki aşkı yeniden yorumlarken öne çıkardığı tema hangisidir?', 'Bireysel aşkın halka ve topluma hizmetle sınanması', ['Saray entrikaları içinde tahta geçmek için duyulan hırs ve kardeş kavgası', 'Sevgililerin büyü yoluyla taşa dönüşmesi', 'Bir tüccarın servet kazanma serüveni'], 'Nazım\'ın yorumunda Ferhat, Şirin\'e kavuşmaktan çok halka su getirme görevine bağlanır; aşk ile toplumsal sorumluluk karşı karşıya gelir.'),
  ('Nazım Hikmet\'in Kuvâyi Milliye\'si ile Fazıl Hüsnü Dağlarca\'nın Üç Şehitler Destanı arasındaki ortak yön hangisidir?', 'Kurtuluş Savaşı\'nı destan havasında işlemeleri', ['Hece ölçüsüyle yazılmış aşk gazelleri olmaları', 'Garip önsözünün ilkelerine göre ölçüsüz, kafiyesiz ve esprili yazılmış olmaları', 'Divan şiirinin kaside biçimini kullanmaları'], 'İki eser de Millî Mücadele\'yi halkın ve askerin kahramanlığı üzerinden destansı bir dille anlatır.'),
  ('Nazım Hikmet\'in Taranta Babu\'ya Mektuplar, Kuvâyi Milliye ve Memleketimden İnsan Manzaraları gibi eserleri birlikte düşünüldüğünde şiirinin hangi eğilimi açıkça görülür?', 'Kısa lirik şiirden uzun, anlatıya dayalı epik şiire yönelme', ['Uzun şiirden vazgeçip yalnızca iki dizelik özdeyişler ve kısa nükteler yazma', 'Toplumsal konulardan uzaklaşıp saf şiire yönelme', 'Serbest ölçüyü bırakıp aruzla kaside yazma'], 'Bu eserlerde Nazım, roman ve destan özelliklerini şiirde birleştiren geniş soluklu anlatı şiirleri yazmıştır.'),
  ('Hasan Âli Yücel döneminde kurulan Tercüme Bürosu\'nda çalışarak çeviriler yapan Garip şairi kimdir?', 'Orhan Veli', ['Ahmed Arif', 'Necip Fazıl', 'Behçet Kemal Çağlar'], 'Orhan Veli, Millî Eğitim Bakanlığı Tercüme Bürosu\'nda çalışmış; Fransızcadan pek çok çeviri yapmıştır.'),
  ('Sabahattin Ali\'nin \'Aldırma gönül aldırma\' nakaratlı ünlü şiirini yazdığı yer hangisidir?', 'Sinop Cezaevi', ['Bursa Cezaevi', 'Kalamış Köşkü', 'Rumelihisarı Aşiyan'], 'Sabahattin Ali bu şiiri 1930\'larda Sinop Cezaevinde yazmıştır; şiir daha sonra bestelenip yaygınlaşmıştır.'),
  ('Nazım Hikmet ile Necip Fazıl\'ın 1920\'lerin sonunda şiire getirdikleri yenilikler karşılaştırıldığında hangi sonuç doğrudur?', 'Nazım biçimde serbest şiirle, Necip Fazıl heceyi koruyarak içerikte metafizik derinlikle yenilik getirmiştir.', ['İkisi de Garip önsözünün ilkelerine uyarak ölçü ve kafiyeyi tamamen kaldırmıştır.', 'İkisi de aruzla yazıp divan şiirinin biçimlerini yeniden canlandırmıştır.', 'Nazım dinî-tasavvufi bir şiire, Necip Fazıl ise toplumcu gerçekçi bir şiire yönelmiştir.'], '835 Satır ve Kaldırımlar aynı yıllarda çıkmıştır; biri biçim devrimiyle, diğeri hece içinde yeni bir iç dünya ile şiirimize katkı yapmıştır.'),
  ('Orhan Veli ile Cahit Sıtkı\'nın ölüm temasını işleyişleri karşılaştırıldığında hangi fark öne çıkar?', 'Orhan Veli ölümü ironik ve hafif bir dille, Cahit Sıtkı ise kaygı ve hüzünle ele alır.', ['Orhan Veli ölümü tasavvufi bir vuslat, Cahit Sıtkı ise siyasi bir şehitlik olarak görür.', 'İkisi de ölümden hiç söz etmemiş, yalnız doğa güzelliklerini anlatmıştır.', 'Orhan Veli ölümü aruzla, Cahit Sıtkı ise ölçüsüz düzyazıyla anlatmıştır.'], 'Kitabe-i Seng-i Mezar\'daki nükteli bakış ile Otuz Beş Yaş\'taki ölüm kaygısı bu farkı açıkça gösterir.'),
  ('Faruk Nafiz\'in \'Han Duvarları\' ile Cahit Külebi\'nin Anadolu şiirleri karşılaştırıldığında hangi ortak nokta bulunur?', 'İkisinin de Anadolu\'yu ve insanını şiirin konusu yapması', ['İkisinin de aruzla ve divan diliyle yazılmış olması', 'İkisinin de anlamı kapalı, imge yoğun İkinci Yeni şiirleri olması', 'İkisinin de yalnız İstanbul\'un semtlerini anlatması'], 'Her iki şair de Anadolu\'yu konu edinir; ancak Faruk Nafiz bir yolcunun gözüyle, Külebi ise daha içeriden bir duyarlılıkla anlatır.'),
  ('Garip ile Yedi Meşale arasındaki ortak yön aşağıdakilerden hangisidir?', 'İkisinin de kendinden önceki şiir anlayışına tepki olarak ortak bir kitapla ortaya çıkması', ['İkisinin de toplumcu gerçekçiliği savunan ortak ve siyasi bir bildiri yayımlaması', 'İkisinin de yalnızca aruzla yazan şairlerden oluşması', 'İkisinin de İkinci Yeni\'nin bir kolu olarak doğması'], 'Yedi Meşale 1928\'de, Garip 1941\'de ortak kitaplarla ortaya çıkmış ve var olan şiire karşı yeni bir anlayış önermiştir.'),
  ('Garip ile Yedi Meşale arasındaki temel fark hangisidir?', 'Garip ölçü ve kafiyeyi reddederken Yedi Meşale ölçülü şiire bağlı kalmıştır.', ['Garip aruzu, Yedi Meşale serbest ölçüyü savunmuştur.', 'Garip yalnız roman, Yedi Meşale yalnız şiir yazmıştır.', 'Garip dinî, Yedi Meşale toplumcu bir anlayışı benimsemiştir.'], 'Yedi Meşaleciler şiirde yenilik istemekle birlikte ölçü ve ahengi korumuş; Garip ise vezin ve kafiyeyi şiirden atmayı savunmuştur.'),
  ('İkinci Yeni ile Hisar karşılaştırıldığında hangi sonuca ulaşılır?', 'İkisi de Garip\'e karşı çıkmış, ancak İkinci Yeni yenilikçi imgeye, Hisar geleneğe yönelmiştir.', ['İkisi de Garip\'in ilkelerini aynen sürdürmüştür.', 'İkisi de toplumcu gerçekçi şiirin yayın organı olmuştur.', 'İkisi de 1928\'de aynı ortak kitapla ortaya çıkmıştır.'], 'Garip\'in yalınlığına tepki ortak noktadır; fakat İkinci Yeni dili saptıran modernist bir şiir, Hisar ise gelenekçi ve millî bir şiir savunmuştur.'),
  ('Mavi hareketi ile İkinci Yeni\'nin ortak noktası aşağıdakilerden hangisidir?', 'İkisinin de 1950\'lerde Garip\'in yalınlığına tepki olarak doğması', ['İkisinin de hece ölçüsünü tek ölçü olarak benimsemesi', 'İkisinin de İslami bir medeniyet düşüncesine ve diriliş fikrine dayanması', 'İkisinin de Yedi Meşale\'nin devamı sayılması'], 'Her iki hareket de Garip\'in tükenmeye başlayan şiirine karşı yeni bir şiir dili arar; Mavi toplumcu bir içerikte, İkinci Yeni bireysel ve imgeci bir yolda ayrışır.'),
  ('Ahmed Arif ile Nazım Hikmet\'in şiirleri karşılaştırıldığında hangi fark söylenebilir?', 'Ahmed Arif\'te bir yörenin ağzı ve epik-lirik coşku, Nazım\'da daha geniş bir dünya görüşü ve biçim çeşitliliği öne çıkar.', ['Ahmed Arif aruzla, Nazım heceyle yazmıştır.', 'Ahmed Arif dinî-tasavvufi, Nazım ise saf şiir çizgisinde yazmıştır.', 'Ahmed Arif uzun manzum romanlar, Nazım ise yalnız dörtlükler yazmıştır.'], 'İkisi de toplumcudur; ancak Ahmed Arif tek kitaplık şiirinde Doğu Anadolu\'nun sesini taşırken Nazım çok farklı biçimlerde, geniş bir dünya ölçeğinde yazmıştır.'),
  ('Edip Cansever ile Cemal Süreya karşılaştırıldığında hangi fark öne çıkar?', 'Cansever\'de varoluşçu bunalım ve dramatik yapı, Süreya\'da aşk, ten ve dil oyunları ağır basar.', ['Cansever hece, Süreya aruz kullanmıştır.', 'Cansever Garip\'e, Süreya Hisar\'a bağlıdır.', 'Cansever dinî, Süreya ise memleketçi bir şiir yazmıştır.'], 'İkisi de İkinci Yeni şairidir; ancak Cansever\'in şiiri trajik ve dramatik, Süreya\'nınki ise aşkın, tenin ve ironik dilin şiiridir.'),
  ('Ece Ayhan ile İlhan Berk\'in İkinci Yeni içindeki konumları karşılaştırıldığında hangisi doğrudur?', 'Ece Ayhan tarihsel ve toplumsal kıyıdakilerle, İlhan Berk ise nesneler ve sözcüklerle ilgilenmiştir.', ['İkisi de Hisar dergisinin kurucusudur.', 'İkisi de yalnızca hece ölçüsüyle yazmıştır.', 'İkisi de Garip önsözünü birlikte kaleme almıştır.'], 'Ece Ayhan\'ın sivil şiiri resmî tarihin dışında kalanlara yönelirken İlhan Berk şiirin nesnelerine ve dilin kendisine odaklanmıştır.'),
  ('Behçet Necatigil ile Cahit Külebi\'nin şiirleri karşılaştırıldığında aralarındaki fark nasıl özetlenebilir?', 'Necatigil şehirli orta sınıfı ve evi, Külebi ise Anadolu\'yu ve kır insanını anlatır.', ['Necatigil aruzla, Külebi Fransızca yazmıştır.', 'Necatigil Garip\'in, Külebi İkinci Yeni\'nin kurucusudur.', 'İkisi de yalnızca İslami-tasavvufi şiirler yazmıştır.'], 'İkisi de topluluk dışı şairlerdir; Necatigil\'in dünyası ev ve aile, Külebi\'ninki ise Anadolu ve türküdür.'),
  ('Sezai Karakoç ile Nazım Hikmet\'in \'Bedreddin\', \'Hızır\' gibi tarihî ya da efsanevi figürlere yönelmeleri hangi ortak eğilimi gösterir?', 'Geçmişten alınan figürler aracılığıyla kendi dünya görüşlerini dile getirme', ['Geçmişi tamamen unutup yalnız bugünü anlatma', 'Tarihî figürleri yalnız mizah malzemesi yapma', 'Yalnızca çocuk masallarına uygun, olağanüstü güçleri olan kahramanlar seçme'], 'Nazım Şeyh Bedreddin\'de devrimci, Karakoç Hızırla Kırk Saat\'te manevi bir dünya görüşünü tarihî-efsanevi figürlerle anlatır.'),
  ('Attila İlhan ile Orhan Veli\'nin şiirde \'halk\' kavramına yaklaşımları karşılaştırıldığında hangisi doğrudur?', 'Orhan Veli halkın zevkine ve diline yönelirken Attila İlhan halkı toplumsal-siyasal bir bilinçle ele alır.', ['İkisi de halkı küçümseyip yalnız saray zevkine seslenmiştir.', 'Orhan Veli halkı sınıf mücadelesi içinde, Attila İlhan ise yalnız mizahla anlatmıştır.', 'İkisi de halk sözcüğünü hiç kullanmamış, yalnız doğayı anlatmıştır.'], 'Garip önsözü kalabalığın zevkini savunur; Attila İlhan ise Mavi\'den itibaren toplumcu-gerçekçi bir bilinçle halka yönelir.'),
  ('Necip Fazıl ile Sezai Karakoç arasındaki bağ en doğru biçimde nasıl açıklanır?', 'İkisi de İslami düşünceyi şiire ve dergiciliğe taşımış; Karakoç bunu İkinci Yeni\'nin moderne açık diliyle sürdürmüştür.', ['Karakoç, Necip Fazıl\'ın Garip\'teki şiir arkadaşıdır.', 'İkisi de aynı yıl doğmuş ve aynı ortak kitabı yayımlamıştır.', 'Necip Fazıl, Karakoç\'un Diriliş dergisini kapatmak için mücadele etmiştir.'], 'Necip Fazıl Büyük Doğu ile, Karakoç Diriliş ile İslami düşünceyi yaymış; Karakoç\'un şiir dili ise İkinci Yeni\'ye yakındır.'),
  ('Gülten Akın ile Didem Madak\'ın şiirleri hangi yönüyle benzerlik gösterir?', 'Kadın deneyimini ve gündelik hayatın ayrıntılarını şiirin merkezine almalarıyla', ['Hece ölçüsüyle akıncı destanları yazmalarıyla', 'Divan şiirinin gazel biçimini aynen sürdürmeleriyle', 'Garip\'in ortak kitabında birlikte yer alıp aynı önsözü imzalamalarıyla'], 'Farklı kuşaklardan bu iki şair kadın sesini, ev içi ve gündelik yaşamın ayrıntılarını şiirleştirmiştir.'),
  ('Ahmet Hamdi Tanpınar\'ın şiir ve sanat anlayışının biçimlenmesinde hocası olarak en büyük etkiyi yapan şair kimdir?', 'Yahya Kemal Beyatlı', ['Mehmet Akif Ersoy', 'Tevfik Fikret', 'Ziya Gökalp'], 'Tanpınar Darülfünun\'da Yahya Kemal\'in öğrencisi olmuş, ondan geçmişle bağ kurma ve ahenk anlayışını devralmış, ona bir de inceleme kitabı ayırmıştır.'),
  ('Nazım Hikmet \'Tahir ile Zühre Meselesi\' şiirinde halk hikâyesine gönderme yaparak hangi düşünceyi savunur?', 'Sevda uğruna ölmenin değil, bir dava ve halk için yaşayıp ölmenin değerli olduğu', ['Aşk uğruna her şeyi bırakıp dağlara çekilmenin en büyük erdem olduğu', 'Sevgililerin ancak masallarda kavuşabileceği', 'Halk hikâyelerinin tamamen unutulması gerektiği'], 'Şiirde \'Tahir olmak da ayıp değil, Zühre olmak da\' denir; ancak asıl yücelik insanlık için verilen mücadelede görülür.'),
  ('Ahmed Arif\'in \'Adiloş Bebenin Ninnisi\' şiirinde ninni biçimini seçmesinin şiire kattığı anlam hangisidir?', 'Bebeğe söylenen sözlerin içine yoksulluğun ve zulmün acısını yerleştirmesi', ['Şiiri yalnızca çocukları uyutmaya yarayan hafif ve eğlenceli bir tekerlemeye dönüştürmesi', 'Divan şiirinin kaside geleneğini yeniden canlandırması', 'Konuyu tamamen masal dünyasına taşıyıp gerçeklikten kopması'], 'Ahmed Arif ninninin şefkatli sesine Doğu\'nun acılarını ve direnme isteğini sığdırarak güçlü bir karşıtlık kurar.'),
  ('Behçet Necatigil\'in isimler sözlüğünün yanında hazırladığı ve edebî yapıtları tanıtan başvuru kitabı hangisidir?', 'Edebiyatımızda Eserler Sözlüğü', ['Türk Edebiyatında Hikâye ve Roman', 'Edebiyatımızda Dergiler Tarihi', 'Türk Şiiri Sözlüğü'], 'Necatigil, Edebiyatımızda İsimler Sözlüğü\'nden sonra Edebiyatımızda Eserler Sözlüğü\'nü de hazırlamıştır.'),
  ('Cahit Sıtkı Tarancı ile Ziya Osman Saba\'nın ömür boyu süren dostluğunun başladığı okul hangisidir?', 'Galatasaray Lisesi', ['Ankara Erkek Lisesi', 'Kabataş Erkek Lisesi', 'Vefa Lisesi'], 'İki şair Galatasaray Lisesinde tanışmış; Cahit Sıtkı\'nın Ziya\'ya mektupları bu dostluğun belgesidir.'),
  ('Necip Fazıl\'ın gençliğinde felsefe öğrenimi için gittiği şehir ve okul hangisidir?', 'Paris, Sorbonne', ['Berlin, Humboldt', 'Londra, Oxford', 'Moskova, KUTV'], 'Necip Fazıl Darülfünun\'da felsefe okuduktan sonra Paris\'e gönderilmiş, Sorbonne\'da öğrenim görmüştür. Moskova\'daki KUTV Nazım Hikmet\'le ilişkilidir.'),
  ('1950\'lerde toplumcu şiirin sesinin kısılması ile 1960\'larda yeniden yükselmesi karşılaştırıldığında hangi sonuca ulaşılır?', 'Şiir anlayışlarındaki değişimler dönemin siyasal ve toplumsal ortamıyla yakından ilişkilidir.', ['Şiir anlayışları siyasal ortamdan tamamen bağımsız gelişmiştir.', 'Toplumcu şiir 1950\'lerde, baskıların en az olduğu yıllarda en parlak dönemini yaşamıştır.', 'Toplumcu şiir 1960\'larda tamamen ortadan kalkmıştır.'], 'Baskı dönemlerinde şairler dolaylı ve bireysel söyleme, özgürlük dönemlerinde ise açık toplumsal söyleme yönelmiştir.'),
  ('Nazım Hikmet\'in 1961\'de yazdığı ve \'1902\'de doğdum / doğduğum şehre dönmedim bir daha\' dizeleriyle başlayan şiirinin adı nedir?', 'Otobiyografi', ['Hasret ve Gurbet Üstüne', 'Yaşamaya Dair', 'Davet'], '\'Otobiyografi\' şiirinde Nazım kendi hayatını, sürgünlüğünü ve inancını kısa ve yalın dizelerle özetler.'),
  ('Nazım Hikmet\'in \'Mavi Gözlü Dev, Minnacık Kadın ve Hanımeli\' şiirinde dev ile kadının ayrılmasının nedeni nasıl yorumlanabilir?', 'Büyük bir yüreğin, küçük ve rahat bir mutluluk arayan dünyaya sığamaması', ['Devin kadını bir büyüyle taşa çevirmesi', 'Kadının deve âşık olup onunla birlikte köyünü ve ailesini terk ederek dağlara kaçması', 'İkisinin de savaşa gidip birbirini unutması'], 'Dev, kadının istediği hanımelli küçük eve sığamaz; kadın rahat bir yaşam için başkasını seçer. Şiir büyük ülkülerle küçük hesaplar arasındaki çatışmayı anlatır.'),
  ('İsmet Özel\'in İslami dönemine geçişini simgeleyen ve adını inanç esaslarını sayan dua metninden alan şiiri hangisidir?', 'Amentü', ['Çile', 'Mona Roza', 'Sakarya Türküsü'], '\'Amentü\' İsmet Özel\'in inanç merkezli şiirlerinden en tanınmışıdır. Çile ve Sakarya Türküsü Necip Fazıl\'ın, Mona Roza Sezai Karakoç\'un şiiridir.'),
  ('Cahit Sıtkı Tarancı\'nın yaşama sevincini ve ölüm kaygısını birlikte dile getirdiği \'Gün Eksilmesin Penceremden\' şiirinin başlığı şairin hangi isteğini yansıtır?', 'Hayatın ışığından ve güzelliğinden hiç yoksun kalmamak', ['Bir an önce ölüp ebedî hayata kavuşmak', 'Pencereyi kapatıp dünyadan elini eteğini çekerek tek başına yaşamak', 'Savaşa katılıp kahramanca ölmek'], 'Ölüm korkusu taşıyan Cahit Sıtkı, gün ışığının penceresinden eksilmemesini dileyerek yaşama tutunma isteğini dile getirir.'),
  ('Nazım Hikmet\'in şiirlerinde sık görülen \'umut\' teması için en uygun değerlendirme hangisidir?', 'Hapis ve sürgün gibi ağır koşullara karşın geleceğe duyulan inancın şiirin taşıyıcı duygusu olması', ['Umudun yalnızca dinî bir kurtuluş beklentisi olarak işlenmesi', 'Umudun tamamen reddedilip yerine kapkara bir karamsarlığın ve çaresizliğin öne çıkarılması', 'Umudun yalnızca bireysel bir aşk sevinci olarak görülmesi'], 'Ben İçeri Düştüğümden Beri ve En Güzel Deniz gibi şiirlerde Nazım, koşullar ne olursa olsun insanlığın daha güzel bir geleceğine inancını korur.'),
  ('Nazım Hikmet\'in şiirinde kişisel aşk ile toplumsal dava arasındaki ilişki nasıl kurulur?', 'İkisi birbirini besleyen, iç içe geçmiş duygular olarak işlenir.', ['Aşk tamamen yasaklanır, yalnızca dava anlatılır.', 'Dava tamamen unutulur, yalnızca aşk anlatılır.', 'Aşk ve dava, birbirini yok etmeye çalışan iki düşman güç olarak karşı karşıya getirilir.'], 'Piraye ve Vera\'ya yazdığı şiirlerde sevgili, memleket ve insanlık sevgisiyle birleşir; aşk da davanın bir parçası olur.'),
  ('Garip şiirlerinin çoğunda şiirin son dizesinde beklenmedik bir esprinin yer alması hangi işlevi görür?', 'Okurda şaşırtma yaratıp sıradan bir durumu ironik biçimde aydınlatmak', ['Şiirin aruz kalıbını tamamlamak için hece eklemek', 'Okura dinî bir öğüt vermek amacıyla şiiri bir dua ve yakarışla bitirerek yüceltmek', 'Şiiri bir halk destanının giriş bölümüne dönüştürmek'], 'Garip şiirinde nükteli son, gündelik bir durumu beklenmedik bir açıdan göstererek şiirin anlamını tek bir vuruşta toplar.'),
  ('Garip hareketinin Türk şiirine getirdiği en kalıcı yenilik olarak hangisi gösterilebilir?', 'Şiiri gündelik hayata ve sıradan insana açarak şiir dilini sadeleştirmesi', ['Aruzu yeniden canlandırıp divan biçimlerini yaygınlaştırması', 'Şiiri ilk kez dinî ve tasavvufi konularla tanıştırıp tekke geleneğini yeniden canlandırması', 'Destan türünü Türk edebiyatına ilk kez getirmesi'], 'Garip\'in yalınlığı sonradan eleştirilse de şiirin konusunu ve dilini genişletmesi, sonraki bütün kuşakları etkilemiştir.'),
  ('Garip şiirine yöneltilen eleştirilerden biri olarak aşağıdakilerden hangisi gösterilebilir?', 'Şiiri yüzeysel bir şakaya ve basit bir anlatıma indirgeme tehlikesi taşıması', ['Şiiri fazlasıyla süslü, Arapça ve Farsça tamlamalarla ağırlaştırıp halktan uzaklaştırması', 'Yalnızca dinî konuları işleyip gündelik hayatı dışlaması', 'Anlamı kapalı imgelerle okuru yorması'], 'Hisar, Mavi ve İkinci Yeni çevreleri Garip\'i şiiri sıradanlaştırmak ve derinlikten yoksun bırakmakla eleştirmiştir.'),
  ('Cemal Süreya\'nın Papirüs dergisini çıkarması ve şiir üzerine yazılar yazması, İkinci Yeni içindeki rolü hakkında ne gösterir?', 'Hareketin hem şairi hem de sözcüsü ve kuramcısı olduğunu', ['Hareketten tamamen kopup roman yazmaya geçtiğini ve şiiri bıraktığını', 'Garip\'in önsözünü yeniden yazdığını', 'Hisar\'ın gelenekçi çizgisine katıldığını'], 'Cemal Süreya şiirleri kadar düzyazılarıyla da İkinci Yeni\'yi savunmuş, şiir tartışmalarının merkezinde yer almıştır.'),
  ('Cemal Süreya\'nın \'Beni Öp Sonra Doğur Beni\' kitabının adında görülen tutum, şiirinin hangi özelliğini yansıtır?', 'Alışılmış söz sırasını ve anlamı ters yüz eden şaşırtıcı bir dil kullanımı', ['Divan şiirinin kalıplaşmış tamlamalarına bağlılık', 'Halk destanlarındaki kahramanlık ölçülerine uyma', 'Yalnızca öğretici ve ahlaki öğüt verme amacıyla açık ve düz bir dil kullanma'], 'Öpmekten sonra doğurmanın gelmesi gibi beklenmedik bir sıralama, Süreya\'nın dili şaşırtıcı ve duygusal biçimde büken tavrının örneğidir.'),
  ('Turgut Uyar\'ın şiirinde sıkça görülen \'Arabistan\', \'geyik\', \'tütün\' gibi imgelerin işlevi en iyi hangi seçenekte açıklanır?', 'Somut nesneleri gerçek anlamlarının ötesinde, duygu ve özlem yüklü imgelere dönüştürmek', ['Coğrafya bilgisi vermek amacıyla uzak ülkeleri ve yaban hayvanlarını okura tanıtmak', 'Tarım ürünlerinin ekonomik değerini anlatmak', 'Halk masallarındaki kahramanları olduğu gibi aktarmak'], 'Uyar\'ın imgeleri gerçek göndergelerinden kopar; Arabistan bir düş ülkesine, geyik bir özleme dönüşür.'),
  ('Turgut Uyar\'ın subaylıktan ayrılıp İstanbul\'a yerleşmesinin ardından yazdığı şiirlerde şehir hayatının öne çıkması hangi temayı güçlendirmiştir?', 'Kalabalık içinde yalnızlık ve modern bireyin bunalımı', ['Askerî zaferlerin coşkulu övgüsü', 'Kırsal hayatın sükûnetine duyulan bağlılık', 'Tasavvufi vuslat, tevhit düşüncesi ve dervişlerin sema törenleri'], 'Her Pazartesi gibi kitaplarda şehirli bireyin tekdüze, yabancılaşmış hayatı ve iç sıkıntısı öne çıkar.'),
  ('Edip Cansever\'in \'Ben Ruhi Bey Nasılım\' gibi kitaplarında bir kişinin iç sesini uzun bir şiir boyunca izlemesi, şiirine hangi türün özelliklerini katar?', 'Romanın ve tiyatronun anlatı ve karakter özelliklerini', ['Atasözlerinin ve deyimlerin kısa, kalıplaşmış ve öğüt veren yapısını', 'Bilmecenin soru-cevap düzenini', 'Mektubun resmî hitap kalıplarını'], 'Cansever, karakter yaratma ve iç monolog gibi roman ve tiyatro tekniklerini uzun şiirlerine taşımıştır.'),
  ('Edip Cansever\'in \'Umutsuzlar Parkı\' kitabının adı, şiirinin genel ruh hâlini nasıl yansıtır?', 'Modern insanın umutsuzluğunu ve yalnızlığını bir mekân imgesinde toplar.', ['Neşeli bir bayram şenliğini anlatan coşkulu bir havayı gösterir.', 'Köy hayatının bereketini ve tarlada çalışmanın mutluluğunu öven bir doğa sevgisini yansıtır.', 'Kahramanlık destanlarının zafer coşkusunu dile getirir.'], 'Park, insanların bir araya geldiği ama yalnız kaldığı bir yerdir; \'umutsuzlar\' sözcüğü Cansever\'in varoluşçu karamsarlığını özetler.'),
  ('Ece Ayhan\'ın şiirinde Osmanlı ve İstanbul tarihinden, özellikle saray ve kenar mahalle ayrıntılarından sık söz etmesinin amacı nedir?', 'Resmî tarihin üstünü örttüğü acıları ve kıyıdaki insanları görünür kılmak', ['Osmanlı padişahlarını ve paşalarını övüp onların savaşlardaki zaferlerini yüceltmek', 'Turistlere İstanbul\'un tarihî yerlerini tanıtmak', 'Divan şiirini aynen taklit ederek kasideler yazmak'], 'Ece Ayhan tarihi alttan, ezilenlerin gözünden okur; sivil şiir anlayışı resmî anlatıya karşı bir hafıza kurar.'),
  ('İkinci Yeni şairlerinin büyük bölümünün daha sonra toplumsal konulara yönelmesi, hareketin hangi yönüne ilişkin yaygın bir eleştiriyle birlikte düşünülebilir?', 'Toplumdan ve anlamdan kopuk olduğu yönündeki eleştiriyle', ['Fazlasıyla siyasi ve sloganlı olduğu yönündeki eleştiriyle', 'Aruza aşırı bağlı kaldığı yönündeki eleştiriyle', 'Yalnız çocuklar için yazıldığı yönündeki eleştiriyle'], 'Toplumcu çevreler İkinci Yeni\'yi anlamsızlık ve toplumdan kaçışla eleştirmiş; 1960\'lardan sonra şairlerin pek çoğu şiirlerine toplumsal duyarlılığı katmıştır.'),
  ('İkinci Yeni\'nin \'anlam\' konusundaki tutumu için en doğru yorum hangisidir?', 'Anlamı tamamen yok saymaktan çok, anlamı tek ve açık bir mesaj olmaktan çıkarmayı amaçlamıştır.', ['Her şiirin tek ve açık bir ahlaki mesaj vermesi gerektiğini savunmuştur.', 'Şiirde anlamın yalnızca halk deyimleriyle kurulabileceğini ileri sürmüştür.', 'Anlamı korumak için ölçü ve kafiyeyi zorunlu saymıştır.'], 'İkinci Yeni\'ye \'anlamsız şiir\' denmesine karşın şairler, anlamın çok katmanlı ve okura açık olmasını savunmuşlardır.'),
  ('1940 kuşağı toplumcu şairlerinin Nazım Hikmet\'ten farklı olarak Garip\'ten de etkilenmeleri şiirlerine nasıl yansımıştır?', 'Toplumsal içeriği daha yalın, konuşma diline yakın bir söyleyişle vermelerine', ['Aruzla yazılmış uzun kasideler kaleme almalarına', 'Anlamı kapalı, soyut ve gerçeküstü imgeleri tercih ederek halktan uzaklaşmalarına', 'Şiiri tümüyle bırakıp yalnız tiyatro yazmalarına'], 'Bu kuşak Nazım\'ın toplumcu bakışını Garip\'in sade ve gündelik diliyle birleştirmiştir.'),
  ('1940\'larda toplumcu şiirin gelişmesini zorlaştıran başlıca etken hangisidir?', 'Siyasi kovuşturmalar, toplatılan kitaplar ve şairlerin yargılanması', ['Okurların şiire ilgisinin tamamen bitmesi', 'Kâğıt üretiminin yasaklanması', 'Bütün şairlerin topluca yurt dışına göç edip Türkçe yazmayı bırakması'], 'Nazım\'ın hapiste olduğu bu dönemde Rıfat Ilgaz\'ın Sınıf\'ı gibi kitaplar toplatılmış, toplumcu şairler sık sık yargılanmıştır.'),
  ('1960 kuşağı toplumcu şairlerinin 1940 kuşağından ayrılan yönü hangisidir?', 'İkinci Yeni\'nin imge birikiminden de yararlanarak toplumcu şiiri daha zengin bir dille yazmaları', ['Toplumsal konuları tamamen bırakıp saf şiire yönelmeleri', 'Hece ölçüsüyle memleket manzaraları anlatmaları', 'Aruzu yeniden tek ölçü olarak benimsemeleri'], 'Ataol Behramoğlu ve İsmet Özel gibi şairler İkinci Yeni\'nin imgeci dilini toplumcu bir bakışla birleştirmiştir.'),
  ('Toplumcu gerçekçi şiirde \'umut\' ve \'gelecek\' kavramlarının sıkça vurgulanması neyle açıklanır?', 'Şiirin, adil bir toplum düzenine inanan bir dünya görüşüne dayanması', ['Şairlerin geleceği bilmek için fal baktırması', 'Şiirin yalnızca dinî bir kurtuluş beklentisi ve ahiret umudu taşıması', 'Şairlerin geçmişi tamamen reddetmesi'], 'Toplumcu şiir, bugünün acılarını anlatırken daha adil bir geleceğin mümkün olduğuna inanır; umut bu nedenle temel bir temadır.'),
  ('Ahmed Arif\'in tek kitabının çok uzun süre en çok okunan şiir kitaplarından biri olmasının nedeni olarak hangisi gösterilebilir?', 'Sevda ile direnişi coşkulu, ezgili ve kolay ezberlenen bir dille birleştirmesi', ['Kitabın yalnızca akademisyenlere yönelik ağır bir dille yazılması', 'Kitabın tamamen Fransızca yazılmış olması', 'Kitapta yalnızca divan şiiri şerhlerinin bulunması'], 'Ahmed Arif\'in şiirleri aşk ve özgürlük özlemini güçlü bir ritimle verdiği için geniş okur kitlesine ulaşmış, pek çoğu bestelenmiştir.'),
  ('Ataol Behramoğlu\'nun şiiri için en uygun değerlendirme hangisidir?', 'Toplumcu bir dünya görüşünü sevgi, umut ve lirizmle birleştiren bir şiir', ['Yalnızca dinî ve tasavvufi kavramlara dayanan bir şiir', 'Hiçbir duygu taşımayan, yalnızca biçim denemesi ve ses oyunlarından oluşan bir şiir', 'Aruzla yazılmış divan şiiri taklidi bir şiir'], 'Behramoğlu\'nun şiirinde toplumsal mücadele ile aşk ve insan sevgisi iç içe geçer; dili açık ve lirik bir nitelik taşır.'),
  ('İsmet Özel\'in şiir serüveni, Cumhuriyet dönemi şiirinde hangi genel olguya örnek gösterilebilir?', 'Bir şairin dünya görüşündeki köklü değişimin şiirinin konularını ve tonunu da dönüştürmesine', ['Şairlerin ömür boyu tek bir görüşten hiç ayrılmamasına', 'Şiirin dünya görüşünden tamamen bağımsız kalmasına', 'Şairlerin yalnızca başkalarının şiirlerini çevirmesine'], 'İsmet Özel\'in Marksizmden İslam\'a geçişi, şiirinde isyanın yönünü ve imgelerin kaynağını değiştirmiştir.'),
  ('Hasan Hüseyin Korkmazgil ile Enver Gökçe\'nin şiirlerindeki ortak yön hangisidir?', 'Anadolu halkının söyleyişini toplumcu bir bakışla birleştirmeleri', ['Divan şiirinin gazel biçimini sürdürmeleri', 'İkinci Yeni\'nin kapalı imgeciliğini şiirin tek ve geçerli yolu olarak görmeleri', 'Yalnız çocuklar için tekerleme yazmaları'], 'İki şair de türkü ve halk dilinden beslenen, emekçiyi ve köylüyü anlatan toplumcu şiirler yazmıştır.'),
  ('1960 kuşağının toplumcu şairleri için aşağıdakilerden hangisi doğru değildir?', 'Garip\'in 1941\'deki ortak kitabında şiir yayımlamışlardır.', ['Pek çoğu Halkın Dostları gibi dergilerde yazmıştır.', 'Nazım Hikmet\'in yeniden basılan kitaplarından etkilenmiştir.', 'İkinci Yeni\'nin dil birikiminden yararlanmıştır.'], 'Garip 1941\'de üç şairin ortak kitabıdır; 1960 kuşağı şairleri bu kitapta yer almamıştır.'),
  ('Gülten Akın\'ın \'Kırmızı Karanfil\' ve sonraki kitaplarında görülen yönelim hangisidir?', 'Toplumsal olaylara ve halkın acılarına daha açık bir duyarlılık', ['Toplumdan tamamen kopup yalnız doğa betimlemesine ve kır manzaralarına çekilme', 'Aruza dönerek saray kasideleri yazma', 'Garip\'in esprili şakalarını taklit etme'], '1970\'lerden itibaren Gülten Akın, toplumsal olayları ve ezilenlerin sesini ağıt ve türkü biçimleriyle şiirine taşımıştır.'),
  ('Beş Hececiler\'in Cumhuriyet döneminde de heceyle yazmayı sürdürmesi ve okul kitaplarına girmesi, hece ölçüsünün hangi niteliğini güçlendirmiştir?', '\'Millî ölçü\' olarak benimsenip geniş kitlelerce tanınmasını', ['Yalnız saray şairlerine özgü bir ölçü sayılmasını', 'Şiirden tamamen silinip yalnızca eğlence yerlerinde söylenen şarkı sözlerinde kalmasını', 'Yalnız Fransızca şiirlerde kullanılır hâle gelmesini'], 'Hece, Millî Edebiyat\'tan itibaren \'millî vezin\' olarak benimsenmiş; okul kitapları ve Hececilerin şiirleriyle kuşaklar boyu yaygınlaşmıştır.'),
  ('Memleketçi hece şiirine yöneltilen \'kartpostal şiiri\' benzetmesiyle anlatılmak istenen eleştiri hangisidir?', 'Anadolu\'yu derinliği olmayan, dışarıdan görülmüş güzel manzaralar gibi sunması', ['Şiirlerin yalnızca posta yoluyla dağıtılması', 'Şiirlerin Fransızca kartlara yazılması', 'Şiirlerin anlamının kapalı, imgelerinin ise çözülmesi güç ve soyut olması'], 'Eleştirmenler bu şiirin Anadolu\'yu yaşanmış bir gerçeklik yerine turistik manzaralar gibi işlediğini ileri sürmüştür.'),
  ('Faruk Nafiz Çamlıbel\'in Cumhuriyet döneminde milletvekilliği yapması ve marş sözleri yazması, şairin hangi yönünü gösterir?', 'Şiirini yeni devletin kuruluş ülküsüyle bütünleştiren, kamusal kimliği güçlü bir şair olmasını', ['Siyasetten tamamen uzak durup yalnız aşk şiiri yazmasını', 'Yalnızca yurt dışında yaşayıp Türkçeyi bırakmasını', 'İkinci Yeni\'nin kuramcısı olarak dergi çıkarmasını'], 'Faruk Nafiz, Onuncu Yıl Marşı gibi eserler ve milletvekilliği ile Cumhuriyet\'in kültür hayatında etkin bir rol üstlenmiştir.'),
  ('Ahmet Kutsi Tecer\'in \'Orda bir köy var uzakta\' dizesiyle başlayan şiirindeki köy imgesi nasıl yorumlanabilir?', 'Gidilip görülmese de insanın içinde taşıdığı, aidiyet duygusunun simgesi', ['Şairin her gün işe gidip geldiği bir mahalle', 'Bir haritada yeri kesin olarak gösterilen, nüfusu ve sınırları belli bir yerleşim', 'Şairin yıkılmasını istediği eski bir kasaba'], '\'Gezmesek de tozmasak da / O köy bizim köyümüzdür\' dizeleri köyü coğrafi bir yerden çok içsel bir bağlılığın simgesi yapar.'),
  ('Yedi Meşaleciler\'in yenilik arayışına karşın şiirlerinde Ahmet Haşim etkisinin belirgin olması nasıl yorumlanabilir?', 'Topluluğun yeni bir şiir kurmaktan çok sembolist çizgiyi sürdürdüğü', ['Topluluğun tamamen toplumcu gerçekçi olduğu', 'Topluluğun halk şiirini birebir taklit ettiği', 'Topluluğun ölçüyü, kafiyeyi ve bütün geleneksel biçimleri tümüyle reddettiği'], 'Yenilik iddiasına karşın Yedi Meşale şiiri Haşim\'in imge ve ahenk anlayışını aşamamış; bu da topluluğun etkisini sınırlı kılmıştır.'),
  ('Yedi Meşale topluluğunun kuruluş yılı ile Harf Devrimi\'nin aynı yıla, 1928\'e denk gelmesi hangi gözlemi destekler?', 'Topluluğun, Cumhuriyet\'in kültürel yeniliklerinin yoğunlaştığı bir dönemde ortaya çıktığı', ['Topluluğun Osmanlı sarayının desteğiyle kurulduğu', 'Topluluğun yeni harflere karşı çıkmak ve eski yazıyı korumak amacıyla kurulduğu', 'Topluluğun yalnızca Arap harfleriyle yayın yaptığı'], '1928 yeni harflerin kabul edildiği yıldır; Yedi Meşale de Cumhuriyet\'in ilk on yılındaki yenilenme isteğinin edebiyattaki yansımalarındandır.'),
  ('Saf şiir çizgisindeki şairlerin toplumsal konulara mesafeli durmalarının gerekçesi en iyi hangi görüşle açıklanır?', 'Şiirin değerinin konusundan değil, dilin musikisinden ve imgenin gücünden geldiği görüşü', ['Şiirin yalnızca siyasal propaganda için yazılması gerektiği görüşü', 'Şiirin yalnızca köylüleri eğitmek için var olduğu görüşü', 'Şiirin bütünüyle düzyazıya dönüşmesi gerektiği görüşü'], 'Saf şiir anlayışı, şiiri öğretici ya da ideolojik işlevlerden arındırıp onun özüne, ahenge ve imgeye yönelmeyi savunur.'),
  ('Ahmet Muhip Dıranas\'ın \'Fahriye Abla\' şiirindeki mahalle ve gençlik anılarının şiirde yarattığı temel duygu hangisidir?', 'Geçip giden zamana ve kaybolan bir dünyaya duyulan özlem', ['Gelecekteki bir savaşın coşkulu beklentisi', 'Fabrikadaki işçilerin ağır çalışma koşullarına duyduğu öfke ve isyan', 'Uzay yolculuğuna duyulan merak'], 'Şiir geçmişte kalmış bir mahalleyi ve gençlik heyecanını anarak hüzünlü bir nostalji duygusu yaratır.'),
  ('Cahit Sıtkı Tarancı\'nın şiirinde ölüm korkusu ile yaşama sevincinin bir arada bulunması nasıl değerlendirilebilir?', 'Hayatı ölümün gölgesinde daha değerli gören bir karşıtlığın şiirin gerilimini oluşturması', ['Şairin ölümden hiç söz etmeyip yalnızca neşeyi anlatması', 'Şairin yaşamı tümüyle reddedip yalnızca ölümü övmesi', 'Şairin bu temaları yalnızca mizah malzemesi olarak kullanması'], 'Cahit Sıtkı\'da ölüm bilinci, hayatın güzelliklerine daha sıkı sarılma isteğini doğurur; şiirlerinin dramatik gerilimi buradan gelir.'),
  ('Necip Fazıl\'ın şiirinde \'korku\' duygusunun yeri için en doğru açıklama hangisidir?', 'Ölüm, sonsuzluk ve Tanrı karşısında insanın duyduğu varoluşsal ürpertinin şiirin temel duygusu olması', ['Korkunun yalnızca çocuk masallarındaki canavarlarla sınırlı kalması', 'Korkunun şiirde hiç yer almayıp yalnızca neşenin anlatılması', 'Korkunun yalnızca savaş meydanındaki düşmana yöneltilmesi'], 'Necip Fazıl\'ın şiiri, metafizik sorular karşısında insanın yaşadığı ürperti ve tedirginlik üzerine kuruludur.'),
  ('Necip Fazıl\'ın \'Çile\' adını hem bir şiirine hem de toplu şiirlerine vermesi neyi gösterir?', 'Şairin hayatını ve şiirini manevi bir sınanma yolculuğu olarak görmesini', ['Şairin şiirlerini yalnızca çocuklar için yazmasını', 'Şairin bütün şiirlerini başka bir şairden çevirmesini', 'Şairin şiiri bırakıp romana geçtiğini ilan etmesini'], 'Çile, tasavvufta nefsi terbiye için çekilen sıkıntıdır; Necip Fazıl kendi iç serüvenini bu kavramla özetler.'),
  ('Mavi hareketinin şiir tarihindeki etkisinin sınırlı kalması en çok hangi nedene bağlanır?', 'Kuramsal tartışmaları güçlü olsa da kalıcı bir şiir birikimi bırakan şair sayısının az olması', ['Derginin hiç yayımlanamamış olması', 'Hareketin yalnızca aruzla ve divan nazım biçimleriyle yazan şairlerden oluşması', 'Üyelerinin Hisar dergisinin kurucusu olması'], 'Mavi daha çok Attila İlhan\'ın kuramsal yazılarıyla anılır; çevresindeki gençlerin çoğu sonradan başka türlere ve yollara yönelmiştir.'),
  ('Attila İlhan\'ın şiirinde sinema ve kentsel imgelerin, özellikle sisli bulvarların ve gece hayatının yer alması hangi özelliği yansıtır?', 'Modern şehir hayatını gerilimli ve hüzünlü bir atmosferle işlemesini', ['Kır hayatını ve köy insanını idealize eden huzurlu, pastoral bir bakışı', 'Tasavvufi bir zühd ve dünyadan el çekme isteğini', 'Yalnızca çocuklar için yazılmış neşeli tekerlemeleri'], 'Sisler Bulvarı\'ndan başlayarak Attila İlhan\'ın şiiri kentin gece hayatını, yalnızlığı ve aşkı sinemasal bir atmosferle anlatır.'),
  ('Attila İlhan\'ın şiiri için hangisi söylenemez?', 'Ölçü ve ahengi tamamen reddedip yalnızca düzyazı şiir yazmıştır.', ['Aşk ve hüzün temalarını yoğun biçimde işlemiştir.', 'Toplumcu bir duyarlılık taşımıştır.', 'Osmanlıca sözcüklere ve eski şiirin çağrışımlarına yer vermiştir.'], 'Attila İlhan\'ın şiiri ahenkli ve ritimlidir; pek çok şiiri bu yüzden bestelenmiştir. Düzyazı şiirle yetindiği söylenemez.'),
  ('Hisar şairlerinin şiirlerinde sıkça görülen temalar hangi seçenekte doğru verilmiştir?', 'Aşk, ayrılık, yurt sevgisi ve millî tarih', ['Sınıf çatışması, grev ve fabrika', 'Gerçeküstü imgeler, absürt durumlar ve bilinçaltı', 'Uzay, teknoloji ve bilim kurgu'], 'Hisarcılar bireysel duygular ile millî duyarlılığı birlikte işlemiş; aşk, hasret, yurt sevgisi ve tarih başlıca temalar olmuştur.'),
  ('Hisar çevresinin sanat anlayışı için en uygun değerlendirme hangisidir?', 'Ne yalnız toplum için ne yalnız sanat için; gelenekle bağını koruyan dengeli bir yol arayışı', ['Sanatın yalnızca devrim için var olduğunu savunan militan bir anlayış', 'Geleneği tamamen reddeden avangart bir anlayış', 'Şiiri yalnızca ses oyunu olarak gören biçimci bir anlayış'], 'Hisarcılar Garip\'in sıradanlaştırmasına ve toplumcu şiirin ideolojik tavrına karşı orta bir yol aramıştır.'),
  ('Sezai Karakoç\'un \'Mona Roza\' şiirinin ve ardından gelen şiirlerinin yaygınlaşmasında hangi etken önemli rol oynamıştır?', 'Lirik aşk şiirini derin bir hasret ve manevi arayışla birleştirmesi', ['Şiirin yalnızca bir okul marşı olarak yazılması', 'Şiirin aruzla, kaside biçiminde ve övgü amacıyla yazılmış olması', 'Şiirin Garip önsözünün bir parçası olarak basılması'], 'Mona Roza\'da bireysel aşk acısı, Karakoç\'un sonraki şiirlerinde manevi ve medeniyete dair bir özleme dönüşür.'),
  ('Sezai Karakoç\'un \'Taha\'nın Kitabı\' adlı eserinin adı, şiirinin hangi kaynağına işaret eder?', 'İslam peygamberine ve Kur\'an kültürüne', ['Antik Yunan mitolojisine ve Olympos tanrılarına', 'Budist inançlarına', 'Fransız sembolizmine'], 'Taha, Kur\'an\'da bir surenin adıdır ve Hz. Muhammed\'e işaret eder; Karakoç\'un şiirinin İslami kaynaklardan beslendiğini gösterir.'),
  ('1970\'lerde Mavera ve Edebiyat dergileri çevresinde toplanan şairlerin ortak eğilimi hangisidir?', 'İslami bir dünya görüşünü modern şiir diliyle ifade etmek', ['Hece ölçüsüyle memleket manzaraları anlatmak', 'Garip\'in ilk dönemini aynen sürdürmek', 'Marksist bir sınıf mücadelesini ve işçi hareketini savunmak'], 'Bu dergiler Sezai Karakoç\'tan etkilenen, inanç merkezli ama biçimde modern bir şiir yazan kuşağı bir araya getirmiştir.'),
  ('Fazıl Hüsnü Dağlarca\'nın şiir üretimi için hangi yargı doğrudur?', 'Çok sayıda kitap yayımlayarak Cumhuriyet döneminin en üretken şairlerinden biri olmuştur.', ['Yalnızca tek bir şiir kitabı yayımlamıştır.', 'Bütün şiirlerini aruzla, kaside biçiminde yazmıştır.', 'Şiirlerini yalnızca Fransızca yayımlamıştır.'], 'Dağlarca altmışı aşkın kitapla son derece üretken bir şairdir; tek kitaplık şairlere örnek ise Ahmed Arif\'tir.'),
  ('Behçet Necatigil\'in hem şiir hem radyo oyunu hem de sözlük çalışması yapması, edebiyat hayatı hakkında ne gösterir?', 'Şiirin yanında edebiyat kültürüne çok yönlü katkı yapan bir yazar olduğunu', ['Yalnızca tek bir türde ürün verdiğini', 'Edebiyatı bütünüyle bırakıp ticarete atıldığını ve bir daha yazmadığını', 'Eserlerini sağlığında yayımlatmaktan kaçındığını'], 'Necatigil şair, radyo oyunu yazarı, çevirmen ve sözlük hazırlayıcısı olarak edebiyatımıza farklı alanlarda katkıda bulunmuştur.'),
  ('Cahit Külebi\'nin şiirlerinin pek çoğunun türkü gibi bestelenmeye uygun olması hangi özelliğinden kaynaklanır?', 'Halk türküsünün ritmini, yalınlığını ve tekrarlarını şiirine taşımasından', ['Şiirlerini aruzun ağır kalıplarıyla yazmasından', 'Anlamı tamamen kapalı imgeler kullanmasından', 'Şiirlerini yalnızca ölçüsüz düzyazı biçiminde ve uzun paragraflarla yazmasından'], 'Külebi\'nin şiiri türkü söyleyişine yakın, sade ve ezgili olduğu için kolayca bestelenebilir.'),
  ('Bedri Rahmi Eyüboğlu\'nun şiirinde Anadolu\'ya bakışı için hangisi en doğrudur?', 'Anadolu\'nun renklerini, halk sanatını ve insanını coşkulu ve sevecen bir dille anlatır.', ['Anadolu\'yu yalnız karanlık ve umutsuz bir yer olarak görür.', 'Anadolu\'yu hiç anlatmaz, yalnız Paris\'i işler.', 'Anadolu\'yu yalnızca istatistiklerle betimler.'], 'Ressam şair, Anadolu\'yu bir renk ve motif şöleni olarak, halk kültürüne duyduğu sevgiyle anlatmıştır.'),
  ('Özdemir Asaf\'ın şiirlerinin özdeyiş gibi alıntılanıp geniş kitlelere yayılmasının nedeni hangisidir?', 'Kısa, çarpıcı ve kolayca akılda kalan söz oyunlarına dayanması', ['Uzun destanlar biçiminde yazılmış olması', 'Yalnızca eski harflerle ve sınırlı sayıda basılmış özel bir kitapta yer alması', 'Anlamı tamamen kapalı imgelerden oluşması'], 'Özdemir Asaf\'ın kısa ve keskin dizeleri bir özdeyiş gibi kolayca alıntılanabilir; bu da şiirlerinin yaygınlaşmasını sağlamıştır.'),
  ('Can Yücel\'in toplumsal eleştirisini sunuş biçimi en iyi nasıl tanımlanır?', 'Mizah ve argo ile yumuşatılmış ama keskin bir alaycılıkla', ['Tamamen resmî ve ağır bir hitabetle', 'Yalnızca dinî öğütler biçiminde', 'Hiç eleştiri içermeyen, yalnızca yöneticileri öven bir dille'], 'Can Yücel toplumsal ve siyasal eleştirisini halk diliyle, şaka ve argo aracılığıyla etkili biçimde dile getirir.'),
  ('Topluluk dışı (bağımsız) şairlerin Cumhuriyet şiirindeki yeri için en uygun değerlendirme hangisidir?', 'Herhangi bir hareketin kurallarına bağlanmadan özgün şiir dünyaları kurarak şiirimizi zenginleştirmişlerdir.', ['Hiçbir kalıcı eser bırakmadan unutulmuşlardır.', 'Yalnızca başka şairlerin şiirlerini derleyen antolojiciler olmuşlardır.', 'Tamamı Garip\'in ortak kitabında şiir yayımlamıştır.'], 'Dağlarca, Necatigil, Asaf Halet, Külebi ve Özdemir Asaf gibi şairler topluluk dışında kalmalarına karşın kendine özgü sesleriyle şiirimizin önemli adları olmuştur.'),
  ('Mehmet Akif Ersoy, Mısır\'da geçirdiği yıllardan sonra hastalanarak İstanbul\'a döndüğü hangi yıl hayatını kaybetmiştir?', '1936', ['1923', '1938', '1946'], 'Mehmet Akif 1936\'da İstanbul\'da ölmüştür; cenazesi büyük bir kalabalıkla kaldırılmıştır.'),
  ('Arif Nihat Asya\'nın şiirinde ölçü kullanımı için en doğru yargı hangisidir?', 'Hem hece hem aruzla yazmış, rubai gibi eski biçimleri de kullanmıştır.', ['Yalnızca serbest ölçüyle ve kafiyesiz yazmış, eski biçimlere asla başvurmamıştır.', 'Hiç şiir yazmamış, yalnızca nesir kaleme almıştır.', 'Bütün şiirlerini Fransızca ve aruzla yazmıştır.'], 'Arif Nihat Asya hece ölçüsünü kullanmanın yanında aruzla rubailer de yazmış, iki geleneği bir arada sürdürmüştür.'),
  ('Neyzen Tevfik\'in hiciv şiirlerinin başlıca hedefi hangisidir?', 'İkiyüzlülük, çıkarcılık ve toplumdaki ahlaki çürüme', ['Yalnızca doğa güzellikleri, mevsimlerin değişimi ve kır manzaraları', 'Yalnızca çocuk eğitimi ve okul hayatı', 'Yalnızca uzak ülkelerin tarihi'], 'Neyzen Tevfik, sert ve alaycı diliyle sahtekârlığı, dalkavukluğu ve çıkarcılığı yermiştir.'),
  ('Ziya Osman Saba\'nın şiirinde çocukluk evine ve aile hayatına sık sık dönmesi nasıl yorumlanabilir?', 'Kaybolan güven ve huzur duygusunu geçmişte arama isteği', ['Gelecekteki savaşları önceden haber verme isteği', 'Toplumdaki sınıf çatışmasını ve işçilerin hak arayışını açıklama isteği', 'Batı şehirlerinin modern hayatını övme isteği'], 'Ziya Osman için çocukluk ve ev, ölüm korkusuna ve hayatın sertliğine karşı sığınılan sıcak bir dünyadır.'),
  ('Kemalettin Kamu\'nun \'Ben gurbette değilim, gurbet benim içimde\' dizesinin anlamı için en doğru yorum hangisidir?', 'Gurbetin bir yer değil, insanın içinde taşıdığı bir yalnızlık ve yabancılık duygusu olduğu', ['Şairin hayatı boyunca hiç yolculuk yapmadığı ve doğduğu evden dışarı çıkmadığı', 'Şairin gurbette çok mutlu olduğu', 'Gurbetin yalnızca yurt dışındaki şehirler olduğu'], 'Şair, gurbeti coğrafi bir uzaklıktan içsel bir duyguya dönüştürerek yalnızlığın her yerde süreceğini anlatır.'),
  ('Cumhuriyet\'in ilk kuşağı şairlerinden Kemalettin Kamu ve Ömer Bedrettin Uşaklı\'nın şiirleri hangi topluluğun etkisini taşır?', 'Beş Hececiler\'in memleketçi hece şiirinin', ['İkinci Yeni\'nin kapalı imgeciliğinin', 'Garip\'in ölçüsüz, kafiyesiz ve gündelik dile dayanan şiirinin', 'Mavi\'nin sosyal realizminin'], 'Bu şairler hece ölçüsünü ve Anadolu temalarını Beş Hececiler\'in açtığı yolda sürdürmüştür.'),
  ('Bir şairin hem toplumcu bir başlangıç yapıp hem de sonradan İkinci Yeni\'nin önde gelenleri arasına girmesine örnek olarak hangisi gösterilebilir?', 'İlhan Berk', ['Ahmed Arif', 'Arif Nihat Asya', 'Faruk Nafiz Çamlıbel'], 'İlhan Berk Günaydın Yeryüzü ve Türkiye Şarkısı\'ndaki toplumcu dönemden Galile Denizi ile İkinci Yeni\'ye geçmiştir.'),
  ('Edip Cansever\'in 1964 tarihli kitabının adı, şiirine sahne sanatının hangi türünün yön verdiğini açıkça gösterir?', 'Tragedyalar', ['Komedyalar ve Güldürüler', 'Operetler', 'Skeçler'], 'Tragedyalar adı, Cansever\'in şiirini antik tragedyanın yapısı ve trajik duyarlılığıyla kurduğunu gösterir.'),
  ('Fazıl Hüsnü Dağlarca\'nın Millî Mücadele\'yi işleyen ve 1949\'da yayımlanan destanı hangisidir?', 'Üç Şehitler Destanı', ['Çakırın Destanı', 'Çanakkale Destanı', 'Kuvâyi Milliye'], 'Üç Şehitler Destanı Dağlarca\'nın Millî Mücadele\'yi işleyen destanıdır. Çakırın Destanı (1945) ve Çanakkale Destanı (1965) da onundur ama konuları farklıdır; Kuvâyi Milliye Nazım\'ın eseridir.'),
  ('Sezai Karakoç\'un Diriliş dergisini ilk kez çıkardığı yıl hangisidir?', '1960', ['1943', '1952', '1976'], 'Diriliş 1960\'ta yayımlanmaya başlamıştır. 1943 Büyük Doğu\'nun, 1976 Mavera\'nın çıkış yılıdır.'),
  ('Sezai Karakoç\'un 1969\'da yayımlanan ve adında \'müjde\' anlamına gelen bir sözcük taşıyan kitabı hangisidir?', 'Gül Muştusu', ['Şahdamar', 'Taha\'nın Kitabı', 'Zamana Adanmış Sözler'], 'Muştu, müjde demektir; Gül Muştusu Sezai Karakoç\'un 1969 tarihli kitabıdır.'),
];
